void create_asset_issue_from_asset_management_payload(map payload)
{
                 	info "Freedom payload received: " + payload;
                 	source_id = payload.get("Source_Record_ID");
                 	if(source_id == null)
                 	{
                 		info "Freedom sync stopped: Source_Record_ID is null";
                 		return;
                 	}
                 	source_id = source_id.toLong();
                 	existing = Asset_Issues[Source_Record_ID == source_id && Source_Form == "Asset Management Asset Issues"];
                 	if(existing.count() > 0)
                 	{
                 		info "Freedom sync skipped: issue already exists for Source_Record_ID " + source_id;
                 		return;
                 	}
                 	insert into Asset_Issues
                 	[
                 		Source_Record_ID=source_id
                 		Source_Form="Asset Management Asset Issues"
                 		Issue_Number=payload.get("Issue_Number")
                 		Asset=payload.get("Asset")
                 		Display_Name_Asset=payload.get("Display_Name_Asset")
                 		Current_Site=payload.get("Current_Site")
                 		Current_Custodian=payload.get("Current_Custodian")
                 		Odometer_Reading=payload.get("Odometer_Reading")
                 		Reported_Date=payload.get("Reported_Date")
                 		Issue=payload.get("Issue")
                 		Issue_Description=payload.get("Issue_Description")
                 		Severity=payload.get("Severity")
                 		Issue_Status="Open"
                 		Added_User=zoho.loginuser
                 	]
                 	info "Freedom sync inserted issue: " + payload.get("Issue_Number");
                 }

void fix_sales_vouchers_from_invoice(int invoice_id)
{
                 	inv = Invoice[ID == invoice_id];
                 	if(inv.ID == null)
                 	{
                 		return;
                 	}
                 	total_invoice_paid = 0.0;
                 	for each  p in Payment_Receipt_Details[Payment_Document == "Invoice" && Invoice == inv.ID]
                 	{
                 		total_invoice_paid = total_invoice_paid + ifnull(p.Amount_Allocated,0.0);
                 	}
                 	remaining_paid = total_invoice_paid;
                 	for each  d in Invoice_Details[Invoice == inv.ID && Source_Form == "Sales Voucher"]
                 	{
                 		sv = Sales_Voucher[ID == d.Source_Record_ID];
                 		if(sv.ID != null)
                 		{
                 			sv_total = ifnull(sv.Grand_Total,0.0);
                 			current_credit = ifnull(sv.Amount_Credited,0.0);
                 			pay_for_this_sv = 0.0;
                 			if(remaining_paid >= sv_total)
                 			{
                 				pay_for_this_sv = sv_total;
                 			}
                 			else if(remaining_paid > 0)
                 			{
                 				pay_for_this_sv = remaining_paid;
                 			}
                 			remaining_paid = remaining_paid - pay_for_this_sv;
                 			bal = sv_total - pay_for_this_sv - current_credit;
                 			if(bal < 0)
                 			{
                 				bal = 0.0;
                 			}
                 			update Sales_Voucher[ID == sv.ID]
                 			[
                 				Amount_Paid=pay_for_this_sv
                 				Amount_Credited=current_credit
                 				Balance_Due=bal
                 				Payment_Status=if(bal <= 0,"Paid",if(pay_for_this_sv > 0,"Partially Paid",if(current_credit > 0,"Partially Credited","Unpaid")))
                 			];
                 		}
                 	}
                 }

string Generate_Voucher_Number(int documentKeyId)
{
                 	dk = Document_Key[ID == documentKeyId];
                 	if(dk == null)
                 	{
                 		return "";
                 	}
                 	// ---- Prefix: EXACTLY 3 letters ----
                 	prefix = ifnull(dk.Prefix,"").trim().toUpperCase();
                 	if(!prefix.matches("^[A-Z]{3}$"))
                 	{
                 		return "";
                 	}
                 	// ---- Next number ----
                 	nextNo = ifnull(dk.Next_Number,0);
                 	if(nextNo <= 0)
                 	{
                 		nextNo = 1;
                 	}
                 	// ---- HARD STOP at 999 ----
                 	if(nextNo > 999)
                 	{
                 		return "LIMIT_REACHED";
                 	}
                 	// ---- Pad to 3 digits ----
                 	numStr = nextNo.toString();
                 	if(numStr.length() == 1)
                 	{
                 		numStr = "00" + numStr;
                 	}
                 	else if(numStr.length() == 2)
                 	{
                 		numStr = "0" + numStr;
                 	}
                 	voucherNo = prefix + numStr;
                 	// ---- Increment counter ----
                 	dk.Next_Number=nextNo + 1;
                 	return voucherNo;
                 }

void recalculatePaymentVoucher(int voucherID)
{
                 	voucher = Payment_Made_Voucher[ID == voucherID];
                 	if(voucher.ID == null)
                 	{
                 		return;
                 	}
                 	total_allocated = 0.0;
                 	for each  md in Payment_Made_Details[Payment_Made_Voucher == voucher.ID]
                 	{
                 		total_allocated = total_allocated + ifnull(md.Amount_Allocated,0.0);
                 	}
                 	total_paid = ifnull(voucher.Total_Amount_Paid,0.0);
                 	not_allocated = total_paid - total_allocated;
                 	if(not_allocated < 0)
                 	{
                 		not_allocated = 0.0;
                 	}
                 	voucher.Total_Amount_Allocated=round(total_allocated,2);
                 	voucher.Total_Amount_Not_Allocated=round(not_allocated,2);
                 	if(total_allocated <= 0)
                 	{
                 		voucher.Payment_Made_Voucher_Status="Unassigned";
                 	}
                 	else if(not_allocated > 0)
                 	{
                 		voucher.Payment_Made_Voucher_Status="Partially Assigned";
                 	}
                 	else
                 	{
                 		voucher.Payment_Made_Voucher_Status="Assigned";
                 	}
                 }

void recalculateVoucherMaterialsCost(int voucher_id)
{
                 	if(voucher_id == null)
                 	{
                 		return;
                 	}
                 	v = Voucher_Register[ID == voucher_id];
                 	if(v.ID == null)
                 	{
                 		return;
                 	}
                 	total_cost = 0.0;
                 	// Item Issuing Details
                 	item_rows = Voucher_Issuing_Details[Voucher == voucher_id];
                 	for each  r in item_rows
                 	{
                 		total_cost = total_cost + ifnull(r.Quantity,0.0) * ifnull(r.Cost,0.0);
                 	}
                 	// Employee Issuing Details
                 	emp_rows = Employee_Issuing_Details[Voucher == voucher_id];
                 	for each  er in emp_rows
                 	{
                 		total_cost = total_cost + ifnull(er.Quantity,0.0) * ifnull(er.Cost,0.0);
                 	}
                 	v.Voucher_Cost=round(total_cost,2);
                 }

map syncVoucherFromEmployee(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	if(payload == null)
                 	{
                 		resp.put("message","Payload is null.");
                 		return resp;
                 	}
                 	concrete_id = payload.get("Freedom_Record_ID");
                 	if(concrete_id == null)
                 	{
                 		resp.put("message","Freedom Record ID missing.");
                 		return resp;
                 	}
                 	rec = Voucher_Register[ID == concrete_id];
                 	if(rec.ID == null)
                 	{
                 		resp.put("message","Freedom voucher not found.");
                 		return resp;
                 	}
                 	date_time_out_val = null;
                 	end_time_val = null;
                 	manager_time_val = null;
                 	time_checked_val = null;
                 	hr_time_checked_val = null;
                 	if(ifnull(payload.get("Date_Time_Out"),"") != "")
                 	{
                 		date_time_out_val = payload.get("Date_Time_Out").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("End_Time"),"") != "")
                 	{
                 		end_time_val = payload.get("End_Time").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("Manager_Time"),"") != "")
                 	{
                 		manager_time_val = payload.get("Manager_Time").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("Time_Checked"),"") != "")
                 	{
                 		time_checked_val = payload.get("Time_Checked").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("Hr_Time_Checked"),"") != "")
                 	{
                 		hr_time_checked_val = payload.get("Hr_Time_Checked").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	voucher_status_val = ifnull(payload.get("Voucher_Status"),"");
                 	rec.Date_Time_Out=date_time_out_val;
                 	rec.Hours_Worked=payload.get("Hours_Worked");
                 	if(voucher_status_val != "")
                 	{
                 		rec.Voucher_Status=voucher_status_val;
                 	}
                 	rec.End_Time=end_time_val;
                 	rec.Odometer_End=payload.get("Odometer_End");
                 	rec.Fuel_End_Level=payload.get("Fuel_End_Level");
                 	rec.Manager_Time=manager_time_val;
                 	rec.Cancel_Voucher=payload.get("Cancel_Voucher");
                 	rec.Cancellation_Reason=ifnull(payload.get("Cancellation_Reason"),"");
                 	rec.Seen=payload.get("Seen");
                 	rec.Reason_for_not_Seen=ifnull(payload.get("Reason_for_not_Seen"),"");
                 	rec.Time_Checked=time_checked_val;
                 	rec.Hr_Time_Checked=hr_time_checked_val;
                 	resp.put("ok",true);
                 	resp.put("message","Freedom voucher updated from Employee Management.");
                 	resp.put("id",rec.ID);
                 	return resp;
                 }

map updateAssetIssueStatusFromCrownPlazaManagement(map p)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","");
                 	source_record_id_text = ifnull(p.get("Source_Record_ID"),"").toString().trim();
                 	source_form = ifnull(p.get("Source_Form"),"").toString().trim();
                 	if(source_record_id_text == "")
                 	{
                 		resp.put("message","Source_Record_ID is required.");
                 		return resp;
                 	}
                 	if(source_form != "Crown Plaza Management - Asset Issues")
                 	{
                 		resp.put("message","The Asset Issue is not linked to Crown Plaza Management.");
                 		return resp;
                 	}
                 	source_record_id = source_record_id_text.toLong();
                 	crown_plaza_issue = Asset_Issues[ID == source_record_id];
                 	if(crown_plaza_issue.ID == null)
                 	{
                 		resp.put("message","The corresponding Crown Plaza Management Asset Issue was not found.");
                 		return resp;
                 	}
                 	crown_plaza_issue.Issue_Status="Open";
                 	resp.put("ok",true);
                 	resp.put("message","Crown Plaza Management Asset Issue changed to Open.");
                 	resp.put("Source_Record_ID",crown_plaza_issue.ID);
                 	return resp;
                 }

map updatePaymentMadeStatusFromPayment(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","");
                 	if(payload == null)
                 	{
                 		resp.put("message","Payload is null.");
                 		return resp;
                 	}
                 	source_record_id = ifnull(payload.get("Source_Record_ID"),0).toLong();
                 	voucher_number = ifnull(payload.get("Voucher_Number"),"");
                 	new_status = ifnull(payload.get("Payment_Made_Voucher_Status"),"");
                 	if(source_record_id == 0 && voucher_number == "")
                 	{
                 		resp.put("message","Source Record ID or Voucher Number missing.");
                 		return resp;
                 	}
                 	if(new_status == "")
                 	{
                 		resp.put("message","Payment Made Voucher Status missing.");
                 		return resp;
                 	}
                 	found = false;
                 	if(source_record_id != 0)
                 	{
                 		for each  rec in Payment_Made_Voucher[ID == source_record_id]
                 		{
                 			found = true;
                 			rec.Payment_Made_Voucher_Status=new_status;
                 			resp.put("ok",true);
                 			resp.put("message","Payment Made Voucher status updated.");
                 			resp.put("id",rec.ID);
                 			resp.put("status",new_status);
                 			break;
                 		}
                 	}
                 	if(found == false && voucher_number != "")
                 	{
                 		for each  rec in Payment_Made_Voucher[Payment_Made_Number == voucher_number]
                 		{
                 			found = true;
                 			rec.Payment_Made_Voucher_Status=new_status;
                 			resp.put("ok",true);
                 			resp.put("message","Payment Made Voucher status updated.");
                 			resp.put("id",rec.ID);
                 			resp.put("status",new_status);
                 			break;
                 		}
                 	}
                 	if(found == false)
                 	{
                 		resp.put("message","Payment Made Voucher not found.");
                 	}
                 	return resp;
                 }

map updatePaymentReceiptStatusFromPayment(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	voucher_no = ifnull(payload.get("Voucher_Number"),"");
                 	rec = Payment_Receipt_Voucher[Payment_Receipt_Number == voucher_no];
                 	if(rec.ID == null)
                 	{
                 		resp.put("message","Payment Receipt Voucher not found.");
                 		return resp;
                 	}
                 	rec.Payment_Receipt_Voucher_Status=payload.get("Payment_Receipt_Voucher_Status");
                 	resp.put("ok",true);
                 	resp.put("message","Payment Receipt Voucher status updated.");
                 	resp.put("id",rec.ID);
                 	return resp;
                 }

void update_invoice_payment(int invoice_id)
{
                 	total_allocated = 0.0;
                 	for each  rec in Payment_Receipt_Details[Invoice == invoice_id]
                 	{
                 		total_allocated = total_allocated + ifnull(rec.Amount_Allocated,0.0);
                 	}
                 	inv = Invoice[ID == invoice_id];
                 	if(inv.ID != null)
                 	{
                 		inv.Amount_Paid=total_allocated;
                 		inv.Balance_Due=ifnull(inv.Grand_Total,0.0) - total_allocated;
                 		if(inv.Balance_Due < 0)
                 		{
                 			inv.Balance_Due=0.0;
                 		}
                 		if(total_allocated <= 0)
                 		{
                 			inv.Payment_Status="Not Paid";
                 		}
                 		else if(inv.Balance_Due > 0)
                 		{
                 			inv.Payment_Status="Partially Paid";
                 		}
                 		else
                 		{
                 			inv.Payment_Status="Paid";
                 		}
                 	}
                 }

void asset_issues.asset_issues_update_summary(bigint issue_id)
{
                 	if(issue_id == null)
                 	{
                 		return;
                 	}
                 	issue_rec = Asset_Issues[ID == issue_id];
                 	if(issue_rec.ID == null)
                 	{
                 		return;
                 	}
                 	work_order_task_count = 0;
                 	labour_total = 0.0;
                 	parts_total = 0.0;
                 	total_service_task_cost = 0.0;
                 	tasks = Work_Order_Tasks[Issue == issue_id];
                 	for each  t in tasks
                 	{
                 		work_order_task_count = work_order_task_count + 1;
                 		labour_total = labour_total + ifnull(t.Labour_Total,0.0);
                 		parts_total = parts_total + ifnull(t.Parts_Total,0.0);
                 		total_service_task_cost = total_service_task_cost + ifnull(t.Grand_Total,0.0);
                 	}
                 	issue_rec.Number_Of_Work_Order_Tasks=work_order_task_count;
                 	issue_rec.Labour_Total=round(labour_total,2);
                 	issue_rec.Parts_Total=round(parts_total,2);
                 	issue_rec.Total_Service_Task_Cost=round(total_service_task_cost,2);
                 }

map audit.getLoginAuditInfo()
{
                 	info = Map();
                 	info.put("name",zoho.loginuser);
                 	info.put("email",zoho.loginuserid);
                 	// role is optional (in case you add it later)
                 	try 
                 	{
                 		info.put("role",thisapp.permissions.roleForUser(zoho.loginuserid));
                 	}	catch (e)
                 	{
                 		info.put("role",thisapp.permissions.loginUserProfile());
                 	}
                 	return info;
                 }

map billing.getEmployeeBillPeriod(date work_date, string payment_type)
{
                 	result = Map();
                 	billDate = null;
                 	billNumber = "";
                 	if(payment_type == "Weekly Payment")
                 	{
                 		dayNum = work_date.getDayOfWeek();
                 		if(dayNum == 1)
                 		{
                 			daysToMonday = -6;
                 		}
                 		else
                 		{
                 			daysToMonday = 2 - dayNum;
                 		}
                 		currentWeekMonday = work_date.addDay(daysToMonday);
                 		workWeekThursday = currentWeekMonday.addDay(3);
                 		weekNo = workWeekThursday.getWeekOfYear();
                 		weekYear = workWeekThursday.getYear();
                 		weekTxt = weekNo.toString();
                 		if(weekNo < 10)
                 		{
                 			weekTxt = "0" + weekTxt;
                 		}
                 		billNumber = weekYear.toString() + " Week " + weekTxt;
                 		billDate = currentWeekMonday.addDay(7);
                 	}
                 	if(payment_type == "Monthly Payment")
                 	{
                 		workMonthTxt = work_date.toString("MM");
                 		workYearTxt = work_date.toString("yyyy");
                 		billNumber = workYearTxt + " Month " + workMonthTxt;
                 		currentMonthStart = work_date.toString("01-MM-yyyy").toDate("dd-MM-yyyy");
                 		billDate = currentMonthStart.addMonth(1);
                 	}
                 	result.put("Bill_Date",billDate);
                 	result.put("Bill_Number",billNumber);
                 	return result;
                 }

map billing.recalculateBillTotals(int bill_id)
{
                 	totalResponse = Map();
                 	totalResponse.put("ok",false);
                 	totalResponse.put("bill_id",bill_id);
                 	if(bill_id == null)
                 	{
                 		totalResponse.put("message","Bill ID is required.");
                 		return totalResponse;
                 	}
                 	billRecord = Bill[ID == bill_id];
                 	if(billRecord.ID == null)
                 	{
                 		totalResponse.put("message","Bill record was not found.");
                 		return totalResponse;
                 	}
                 	recalculatedBillTotal = ifnull(Bill_Details[Bill == bill_id].sum(Line_Total),0.0);
                 	if(recalculatedBillTotal == 0)
                 	{
                 		fallbackBillTotal = 0.0;
                 		fallbackLines = Bill_Details[Bill == bill_id];
                 		for each  fallbackLine in fallbackLines
                 		{
                 			fallbackQuantity = ifnull(fallbackLine.Quantity,0.0);
                 			fallbackRate = ifnull(fallbackLine.Rate,0.0);
                 			fallbackBillTotal = fallbackBillTotal + fallbackQuantity * fallbackRate;
                 		}
                 		if(fallbackBillTotal > 0)
                 		{
                 			recalculatedBillTotal = fallbackBillTotal;
                 		}
                 	}
                 	servicesTotal = ifnull(billRecord.Services_Total,0.0);
                 	taxAmount = ifnull(billRecord.Tax_Amount,0.0);
                 	discountAmount = ifnull(billRecord.Discount_Amount,0.0);
                 	amountPaid = ifnull(billRecord.Amount_Paid,0.0);
                 	totalAmount = recalculatedBillTotal + servicesTotal + taxAmount - discountAmount;
                 	if(totalAmount < 0)
                 	{
                 		totalAmount = 0.0;
                 	}
                 	amountDue = totalAmount;
                 	balanceDue = amountDue - amountPaid;
                 	if(balanceDue < 0)
                 	{
                 		balanceDue = 0.0;
                 	}
                 	update Bill[ID == bill_id]
                 	[
                 		Bill_Total=recalculatedBillTotal
                 		Services_Total=servicesTotal
                 		Tax_Amount=taxAmount
                 		Discount_Amount=discountAmount
                 		Total_Amount=totalAmount
                 		Amount_Due=amountDue
                 		Amount_Paid=amountPaid
                 		Balance_Due=balanceDue
                 	];
                 	totalResponse.put("ok",true);
                 	totalResponse.put("message","Bill totals recalculated successfully.");
                 	totalResponse.put("bill_total",recalculatedBillTotal);
                 	totalResponse.put("services_total",servicesTotal);
                 	totalResponse.put("tax_amount",taxAmount);
                 	totalResponse.put("discount_amount",discountAmount);
                 	totalResponse.put("total_amount",totalAmount);
                 	totalResponse.put("amount_paid",amountPaid);
                 	totalResponse.put("balance_due",balanceDue);
                 	return totalResponse;
                 }

map billing.syncEmployeeBilling(int voucher_id)
{
                 	syncResponse = Map();
                 	syncResponse.put("ok",false);
                 	syncResponse.put("message","Employee billing was not processed.");
                 	bill_record_ready = false;
                 	voucherRecord = Voucher_Register[ID == voucher_id];
                 	if(voucherRecord.ID != null)
                 	{
                 		if(voucherRecord.Employee != null)
                 		{
                 			vDate = zoho.currentdate;
                 			if(voucherRecord.Date_Time_In != null)
                 			{
                 				vDate = voucherRecord.Date_Time_In.toDate();
                 			}
                 			sourceVal = ifnull(voucherRecord.Display_Name_Employee,"").trim();
                 			accountVal = ifnull(voucherRecord.Display_Name_Site,"").trim();
                 			siteVal = ifnull(voucherRecord.Display_Name_Site,"").trim();
                 			if(accountVal == "")
                 			{
                 				accountVal = "Unassigned Account";
                 			}
                 			employee_id = voucherRecord.Employee.ID;
                 			empName = ifnull(voucherRecord.Employee.Employee_Name,"").trim();
                 			empNumber = "";
                 			employee_number_value = 0;
                 			if(voucherRecord.Employee.Employee_Number != null)
                 			{
                 				empNumber = voucherRecord.Employee.Employee_Number.toString();
                 				employee_number_value = voucherRecord.Employee.Employee_Number;
                 			}
                 			displayVendorName = empName;
                 			if(empNumber != "")
                 			{
                 				displayVendorName = empName + " - " + empNumber;
                 			}
                 			billName = displayVendorName;
                 			dailyAllowance = 0.0;
                 			weeklyAllowance = 0.0;
                 			monthlySalary = 0.0;
                 			allowanceInput = Map();
                 			allowanceInput.put("Employee_ID",employee_id);
                 			allowanceResp = employee_management.getEmployeeActiveAllowance(allowanceInput);
                 			if(allowanceResp != null)
                 			{
                 				dailyAllowance = ifnull(allowanceResp.get("Daily_Allowance"),0.0);
                 				weeklyAllowance = ifnull(allowanceResp.get("Weekly_Allowance"),0.0);
                 				monthlySalary = ifnull(allowanceResp.get("Monthly_Salary"),0.0);
                 			}
                 			dailyVoucherReference = "";
                 			dailyVoucherDetails = "";
                 			nextVoucherDate = vDate.addDay(1);
                 			employeeDayVouchers = Voucher_Register[Employee == employee_id && Date_Time_In >= vDate && Date_Time_In < nextVoucherDate];
                 			for each  vr in employeeDayVouchers
                 			{
                 				includeVoucher = false;
                 				if(vr.Date_Time_In != null)
                 				{
                 					if(vr.Date_Time_In.toDate() == vDate)
                 					{
                 						includeVoucher = true;
                 					}
                 				}
                 				if(includeVoucher == true)
                 				{
                 					vrNumber = ifnull(vr.Voucher_Number,"").trim();
                 					vrType = "";
                 					if(vr.Voucher_Type != null)
                 					{
                 						vrType = ifnull(vr.Voucher_Type.Voucher_Type,"").trim();
                 					}
                 					if(vrType == "")
                 					{
                 						vrType = ifnull(vr.Display_Name_Voucher_Type,"").trim();
                 					}
                 					if(vrNumber != "")
                 					{
                 						if(dailyVoucherReference == "")
                 						{
                 							dailyVoucherReference = vrNumber;
                 						}
                 						else
                 						{
                 							if(!dailyVoucherReference.contains(vrNumber))
                 							{
                 								dailyVoucherReference = dailyVoucherReference + ", " + vrNumber;
                 							}
                 						}
                 						voucherLine = vrNumber;
                 						if(vrType != "")
                 						{
                 							voucherLine = voucherLine + " - " + vrType;
                 						}
                 						if(dailyVoucherDetails == "")
                 						{
                 							dailyVoucherDetails = voucherLine;
                 						}
                 						else
                 						{
                 							if(!dailyVoucherDetails.contains(voucherLine))
                 							{
                 								dailyVoucherDetails = dailyVoucherDetails + "\n" + voucherLine;
                 							}
                 						}
                 					}
                 				}
                 			}
                 			if(dailyVoucherReference == "")
                 			{
                 				dailyVoucherReference = ifnull(voucherRecord.Voucher_Number,"");
                 			}
                 			if(dailyVoucherDetails == "")
                 			{
                 				dailyVoucherDetails = ifnull(voucherRecord.Voucher_Number,"");
                 				currentVoucherType = "";
                 				if(voucherRecord.Voucher_Type != null)
                 				{
                 					currentVoucherType = ifnull(voucherRecord.Voucher_Type.Voucher_Type,"").trim();
