                 				{
                 					currentVoucherType = ifnull(voucherRecord.Display_Name_Voucher_Type,"").trim();
                 				}
                 				if(currentVoucherType != "")
                 				{
                 					dailyVoucherDetails = dailyVoucherDetails + " - " + currentVoucherType;
                 				}
                 			}
                 			if(dailyAllowance > 0 || weeklyAllowance > 0)
                 			{
                 				periodResp = thisapp.billing.getEmployeeBillPeriod(vDate,"Weekly Payment");
