                 							}
                 							weekVoucherNumber = ifnull(weekVoucher.Voucher_Number,"").trim();
                 							weekVoucherType = "";
                 							if(weekVoucher.Voucher_Type != null)
                 							{
                 								weekVoucherType = ifnull(weekVoucher.Voucher_Type.Voucher_Type,"").trim();
                 							}
                 							if(weekVoucherType == "")
                 							{
                 								weekVoucherType = ifnull(weekVoucher.Display_Name_Voucher_Type,"").trim();
                 							}
                 							if(weekVoucherNumber != "")
                 							{
                 								if(weekVoucherReference == "")
                 								{
                 									weekVoucherReference = weekVoucherNumber;
                 								}
                 								else if(!weekVoucherReference.contains(weekVoucherNumber))
                 								{
                 									weekVoucherReference = weekVoucherReference + ", " + weekVoucherNumber;
                 								}
                 								weekVoucherLine = weekVoucherDate.toString("dd-MMM-yyyy") + " - " + weekVoucherNumber;
                 								if(weekVoucherType != "")
                 								{
                 									weekVoucherLine = weekVoucherLine + " - " + weekVoucherType;
                 								}
                 								if(weekVoucherDetails == "")
                 								{
                 									weekVoucherDetails = weekVoucherLine;
                 								}
                 								else if(!weekVoucherDetails.contains(weekVoucherLine))
                 								{
                 									weekVoucherDetails = weekVoucherDetails + "\n" + weekVoucherLine;
                 								}
                 							}
                 						}
                 					}
                 					qualifyingDateCount = weekDateKeys.size();
                 					if(dailyAllowance > 0)
                 					{
                 						for each  workDate in weekDates
                 						{
                 							workDateVoucherReference = "";
                 							workDateVoucherDetails = "";
                 							workDateSource = sourceVal;
                 							workDateAccount = accountVal;
                 							workDateSite = siteVal;
                 							workDateSourceRecordID = voucherRecord.ID;
                 							for each  dateVoucher in employeeWeekVouchers
                 							{
                 								if(dateVoucher.Date_Time_In != null && dateVoucher.Date_Time_In.toDate() == workDate)
                 								{
                 									dateVoucherNumber = ifnull(dateVoucher.Voucher_Number,"").trim();
                 									dateVoucherType = "";
                 									if(dateVoucher.Voucher_Type != null)
                 									{
                 										dateVoucherType = ifnull(dateVoucher.Voucher_Type.Voucher_Type,"").trim();
                 									}
                 									if(dateVoucherType == "")
                 									{
                 										dateVoucherType = ifnull(dateVoucher.Display_Name_Voucher_Type,"").trim();
                 									}
                 									if(dateVoucherNumber != "")
                 									{
                 										if(workDateVoucherReference == "")
                 										{
                 											workDateVoucherReference = dateVoucherNumber;
                 										}
                 										else if(!workDateVoucherReference.contains(dateVoucherNumber))
                 										{
                 											workDateVoucherReference = workDateVoucherReference + ", " + dateVoucherNumber;
                 										}
                 										dateVoucherLine = dateVoucherNumber;
                 										if(dateVoucherType != "")
                 										{
                 											dateVoucherLine = dateVoucherLine + " - " + dateVoucherType;
                 										}
                 										if(workDateVoucherDetails == "")
                 										{
                 											workDateVoucherDetails = dateVoucherLine;
                 										}
                 										else if(!workDateVoucherDetails.contains(dateVoucherLine))
                 										{
                 											workDateVoucherDetails = workDateVoucherDetails + "\n" + dateVoucherLine;
                 										}
                 									}
                 									workDateSource = ifnull(dateVoucher.Display_Name_Employee,"").trim();
                 									workDateSite = ifnull(dateVoucher.Display_Name_Site,"").trim();
                 									workDateAccount = workDateSite;
                 									if(workDateAccount == "")
                 									{
                 										workDateAccount = "Unassigned Account";
                 									}
                 									workDateSourceRecordID = dateVoucher.ID;
                 								}
                 							}
                 							dailyAllowanceText = "Allowance Type: Daily Allowance";
                 							dailyAllowanceText = dailyAllowanceText + "\nDate: " + workDate.toString("dd-MMM-yyyy");
                 							dailyAllowanceText = dailyAllowanceText + "\nEmployee: " + displayVendorName;
                 							dailyAllowanceText = dailyAllowanceText + "\nSite: " + workDateSite;
                 							dailyAllowanceText = dailyAllowanceText + "\nWeek: " + billNumber;
                 							dailyAllowanceText = dailyAllowanceText + "\nDaily Allowance: " + dailyAllowance.toString();
                 							dailyAllowanceText = dailyAllowanceText + "\n\nVouchers:";
                 							dailyAllowanceText = dailyAllowanceText + "\n" + workDateVoucherDetails;
                 							existingDateDetails = Bill_Details[Bill == employeeBillID && Details_Date == workDate && Expense_Type == "Weekly Payment"];
                 							dailyDetailFound = false;
                 							for each  dateBD in existingDateDetails
                 							{
                 								dateBDText = ifnull(dateBD.Details,"");
                 								if(dateBDText.contains("Allowance Type: Weekly Allowance") == false && dailyDetailFound == false)
                 								{
                 									dateBD.Reference=workDateVoucherReference;
                 									dateBD.Details=dailyAllowanceText;
                 									dateBD.Quantity=1.00;
                 									dateBD.Rate=dailyAllowance;
                 									dateBD.Source=workDateSource;
                 									dateBD.Account=workDateAccount;
                 									dateBD.Current_Site=workDateSite;
                 									dateBD.Source_Record_ID=workDateSourceRecordID;
                 									dateBD.Display_Name_Bill=billName + " - " + billNumber;
                 									dailyDetailFound = true;
                 									bill_record_ready = true;
                 								}
