                 									Bill=employeeBillID
                 									Display_Name_Bill=billName + " - " + billNumber
                 									Details_Date=workDate
                 									Source=workDateSource
                 									Reference=workDateVoucherReference
                 									Details=dailyAllowanceText
                 									Expense_Type="Weekly Payment"
