                 						weeklyAllowanceText = "Allowance Type: Weekly Allowance";
                 						weeklyAllowanceText = weeklyAllowanceText + "\nEmployee: " + displayVendorName;
                 						weeklyAllowanceText = weeklyAllowanceText + "\nWeek: " + billNumber;
                 						weeklyAllowanceText = weeklyAllowanceText + "\nQualifying Dates: " + qualifyingDateCount.toString();
                 						weeklyAllowanceText = weeklyAllowanceText + "\nFixed Weekly Allowance: " + weeklyAllowance.toString();
                 						weeklyAllowanceText = weeklyAllowanceText + "\n\nDaily Records / Vouchers:";
                 						weeklyAllowanceText = weeklyAllowanceText + "\n" + weekVoucherDetails;
                 						allWeeklyPaymentDetails = Bill_Details[Bill == employeeBillID && Expense_Type == "Weekly Payment"];
                 						weeklyAllowanceFound = false;
                 						for each  weeklyAllowanceBD in allWeeklyPaymentDetails
                 						{
                 							weeklyAllowanceBDText = ifnull(weeklyAllowanceBD.Details,"");
                 							if(weeklyAllowanceBDText.contains("Allowance Type: Weekly Allowance") && weeklyAllowanceFound == false)
                 							{
                 								weeklyAllowanceBD.Details_Date=billDate;
                 								weeklyAllowanceBD.Reference=weekVoucherReference;
                 								weeklyAllowanceBD.Details=weeklyAllowanceText;
                 								weeklyAllowanceBD.Quantity=qualifyingDateCount;
                 								weeklyAllowanceBD.Rate=weeklyCalculatedRate;
                 								weeklyAllowanceBD.Source=sourceVal;
                 								weeklyAllowanceBD.Account=accountVal;
                 								weeklyAllowanceBD.Current_Site=siteVal;
                 								weeklyAllowanceBD.Source_Record_ID=voucherRecord.ID;
                 								weeklyAllowanceBD.Display_Name_Bill=billName + " - " + billNumber;
                 								weeklyAllowanceFound = true;
                 								bill_record_ready = true;
                 							}
                 						}
                 						if(weeklyAllowanceFound == false)
                 						{
                 							newWeeklyAllowanceDetailID = insert into Bill_Details
                 							[
                 								Bill=employeeBillID
                 								Display_Name_Bill=billName + " - " + billNumber
                 								Details_Date=billDate
                 								Source=sourceVal
                 								Reference=weekVoucherReference
                 								Details=weeklyAllowanceText
                 								Expense_Type="Weekly Payment"
                 								Quantity=qualifyingDateCount
                 								Rate=weeklyCalculatedRate
                 								Account=accountVal
                 								Current_Site=siteVal
                 								Source_Record_ID=voucherRecord.ID
                 								Source_Form="Crown Plaza Management - Voucher Register"
                 								Bill_Details_Status="Draft"
                 								Added_User=zoho.loginuser
                 							];
                 							if(newWeeklyAllowanceDetailID != null)
                 							{
                 								bill_record_ready = true;
                 							}
                 						}
                 					}
                 					totalsResp = thisapp.billing.recalculateBillTotals(employeeBillID);
                 					info totalsResp;
                 				}
                 			}
                 			specialMonthlyEmployee = false;
                 			if(employee_number_value >= 10000 && employee_number_value <= 20000)
                 			{
                 				specialMonthlyEmployee = true;
                 			}
                 			if(monthlySalary > 0 && specialMonthlyEmployee == false)
                 			{
                 				monthlyPeriodResp = thisapp.billing.getEmployeeBillPeriod(vDate,"Monthly Payment");
                 				monthlyBillDate = monthlyPeriodResp.get("Bill_Date");
                 				monthlyReference = monthlyPeriodResp.get("Bill_Number");
                 				existingMonthlyBill = Bill[Employee_Vendor == employee_id && Bill_Number == monthlyReference && Bill_Type == "Employee Bill"];
                 				monthlyBillID = null;
                 				if(existingMonthlyBill.ID != null)
                 				{
                 					monthlyBillID = existingMonthlyBill.ID;
                 					existingMonthlyBill.Bill_Date=monthlyBillDate;
                 					existingMonthlyBill.Bill_Type="Employee Bill";
                 					existingMonthlyBill.Employee_Vendor=employee_id;
                 					existingMonthlyBill.Display_Name_Vendor=displayVendorName;
                 					existingMonthlyBill.Bill_Name=billName;
                 					existingMonthlyBill.Bill_Number=monthlyReference;
                 				}
                 				else
                 				{
                 					monthlyBillID = insert into Bill
                 					[
                 						Bill_Date=monthlyBillDate
                 						Bill_Type="Employee Bill"
                 						Employee_Vendor=employee_id
                 						Display_Name_Vendor=displayVendorName
                 						Bill_Name=billName
                 						Bill_Number=monthlyReference
                 						Bill_Status="Draft"
                 						Payment_Status="Not Paid"
                 						Added_User=zoho.loginuser
                 					];
                 				}
                 				if(monthlyBillID != null)
                 				{
                 					existingDailyMonthly = Bill_Details[Bill == monthlyBillID && Details_Date == vDate && Expense_Type == "Monthly Payment"];
                 					monthlyDetailText = "";
                 					monthlyDetailText = "Date: " + vDate.toString("dd-MMM-yyyy");
                 					monthlyDetailText = monthlyDetailText + "\nEmployee: " + displayVendorName;
                 					monthlyDetailText = monthlyDetailText + "\nSite: " + siteVal;
                 					monthlyDetailText = monthlyDetailText + "\nMonth: " + monthlyReference;
                 					monthlyDetailText = monthlyDetailText + "\nMonthly Salary: " + monthlySalary.toString();
                 					monthlyDetailText = monthlyDetailText + "\n\nVouchers:";
                 					monthlyDetailText = monthlyDetailText + "\n" + dailyVoucherDetails;
                 					if(existingDailyMonthly.count() == 0)
                 					{
                 						newMonthlyDetailID = insert into Bill_Details
                 						[
                 							Bill=monthlyBillID
                 							Display_Name_Bill=billName + " - " + monthlyReference
                 							Details_Date=vDate
                 							Source=sourceVal
                 							Reference=dailyVoucherReference
                 							Details=monthlyDetailText
                 							Expense_Type="Monthly Payment"
                 							Quantity=1.00
                 							Account=accountVal
                 							Current_Site=siteVal
                 							Source_Record_ID=voucherRecord.ID
                 							Source_Form="Crown Plaza Management - Voucher Register"
                 							Bill_Details_Status="Draft"
                 							Added_User=zoho.loginuser
                 						];
                 						if(newMonthlyDetailID != null)
                 						{
                 							bill_record_ready = true;
                 						}
                 					}
                 					else
                 					{
                 						for each  monthlyBD in existingDailyMonthly
                 						{
                 							monthlyBD.Reference=dailyVoucherReference;
                 							monthlyBD.Details=monthlyDetailText;
                 							monthlyBD.Quantity=1.00;
                 							monthlyBD.Source=sourceVal;
                 							monthlyBD.Account=accountVal;
                 							monthlyBD.Current_Site=siteVal;
                 							monthlyBD.Display_Name_Bill=billName + " - " + monthlyReference;
                 							bill_record_ready = true;
                 							break;
                 						}
                 					}
                 				}
                 			}
                 			if(monthlySalary > 0 && specialMonthlyEmployee == true)
                 			{
                 				specialEmployees = List();
                 				supervisorVoucherList = List();
                 				specialDetailText = "";
                 				specialEmployeeCount = 0;
                 				checkedSpecialEmployees = List();
                 				specialSalaryCache = Map();
                 				// Read only this site's vouchers for the current date.
                 				siteVouchers = Voucher_Register[Display_Name_Site == siteVal && Date_Time_In >= vDate && Date_Time_In < nextVoucherDate];
                 				for each  siteVoucher in siteVouchers
                 				{
                 					isSameDay = false;
                 					if(siteVoucher.Date_Time_In != null)
                 					{
                 						if(siteVoucher.Date_Time_In.toDate() == vDate)
                 						{
                 							isSameDay = true;
                 						}
                 					}
                 					if(isSameDay == true && siteVoucher.Employee != null)
                 					{
                 						thisEmployeeNumber = 0;
                 						if(siteVoucher.Employee.Employee_Number != null)
                 						{
                 							thisEmployeeNumber = siteVoucher.Employee.Employee_Number;
                 						}
                 						if(thisEmployeeNumber >= 10000 && thisEmployeeNumber <= 20000)
                 						{
                 							thisEmployeeID = siteVoucher.Employee.ID;
                 							thisEmployeeKey = thisEmployeeID.toString();
                 							thisMonthlySalary = 0.0;
                 							if(!checkedSpecialEmployees.contains(thisEmployeeKey))
                 							{
                 								checkedSpecialEmployees.add(thisEmployeeKey);
                 								thisAllowanceInput = Map();
                 								thisAllowanceInput.put("Employee_ID",thisEmployeeID);
                 								thisAllowanceResp = employee_management.getEmployeeActiveAllowance(thisAllowanceInput);
                 								if(thisAllowanceResp != null)
                 								{
                 									thisMonthlySalary = ifnull(thisAllowanceResp.get("Monthly_Salary"),0.0);
                 								}
                 								specialSalaryCache.put(thisEmployeeKey,thisMonthlySalary);
                 							}
                 							else
                 							{
                 								thisMonthlySalary = ifnull(specialSalaryCache.get(thisEmployeeKey),0.0);
                 							}
                 							if(thisMonthlySalary > 0)
                 							{
                 								thisEmployeeName = ifnull(siteVoucher.Employee.Employee_Name,"").trim();
                 								thisEmployeeDisplay = thisEmployeeName;
                 								if(thisEmployeeNumber > 0)
                 								{
                 									thisEmployeeDisplay = thisEmployeeName + " - " + thisEmployeeNumber.toString();
                 								}
                 								if(!specialEmployees.contains(thisEmployeeKey))
                 								{
                 									specialEmployees.add(thisEmployeeKey);
                 									specialEmployeeCount = specialEmployeeCount + 1;
                 									if(specialDetailText != "")
                 									{
                 										specialDetailText = specialDetailText + "\n";
                 									}
                 									specialDetailText = specialDetailText + "\n" + thisEmployeeDisplay;
                 								}
                 								thisVoucherNumber = ifnull(siteVoucher.Voucher_Number,"").trim();
                 								thisVoucherType = "";
                 								if(siteVoucher.Voucher_Type != null)
                 								{
                 									thisVoucherType = ifnull(siteVoucher.Voucher_Type.Voucher_Type,"").trim();
                 								}
                 								if(thisVoucherType == "")
                 								{
                 									thisVoucherType = ifnull(siteVoucher.Display_Name_Voucher_Type,"").trim();
                 								}
                 								if(thisVoucherNumber != "")
                 								{
                 									thisVoucherLine = "  - " + thisVoucherNumber;
                 									if(thisVoucherType != "")
                 									{
                 										thisVoucherLine = thisVoucherLine + " - " + thisVoucherType;
                 									}
                 									if(!specialDetailText.contains(thisVoucherLine))
                 									{
                 										specialDetailText = specialDetailText + "\n" + thisVoucherLine;
                 									}
                 								}
                 								thisSupervisorVoucher = ifnull(siteVoucher.Display_Name_Issued_By,"").trim();
                 								if(thisSupervisorVoucher != "")
                 								{
                 									if(!supervisorVoucherList.contains(thisSupervisorVoucher))
                 									{
                 										supervisorVoucherList.add(thisSupervisorVoucher);
                 									}
                 								}
                 							}
                 						}
                 					}
                 				}
                 				specialReference = "";
                 				for each  supervisorVoucher in supervisorVoucherList
                 				{
                 					if(specialReference == "")
                 					{
                 						specialReference = supervisorVoucher;
                 					}
                 					else
                 					{
                 						specialReference = specialReference + ", " + supervisorVoucher;
                 					}
                 				}
                 				if(specialEmployeeCount > 0)
                 				{
                 					specialMonthlyText = "";
                 					specialMonthlyText = "Date: " + vDate.toString("dd-MMM-yyyy");
                 					specialMonthlyText = specialMonthlyText + "\nSite: " + siteVal;
                 					specialMonthlyText = specialMonthlyText + "\nEmployees: " + specialEmployeeCount.toString();
                 					specialMonthlyText = specialMonthlyText + "\n\nEmployees / Vouchers:";
                 					specialMonthlyText = specialMonthlyText + specialDetailText;
                 					existingSpecialMonthly = Bill_Details[Details_Date == vDate && Current_Site == siteVal && Expense_Type == "Monthly Payment" && Source_Form == "Crown Plaza Management - Voucher Register"];
                 					if(existingSpecialMonthly.count() == 0)
                 					{
                 						newSpecialMonthlyDetailID = insert into Bill_Details
                 						[
                 							Details_Date=vDate
                 							Source=siteVal
                 							Reference=specialReference
                 							Details=specialMonthlyText
                 							Expense_Type="Monthly Payment"
                 							Quantity=specialEmployeeCount
                 							Account=accountVal
                 							Current_Site=siteVal
                 							Source_Record_ID=voucherRecord.ID
                 							Source_Form="Crown Plaza Management - Voucher Register"
                 							Bill_Details_Status="Draft"
                 							Added_User=zoho.loginuser
                 						];
                 						if(newSpecialMonthlyDetailID != null)
                 						{
                 							bill_record_ready = true;
                 						}
                 					}
                 					else
                 					{
                 						for each  specialBD in existingSpecialMonthly
                 						{
                 							specialBD.Reference=specialReference;
                 							specialBD.Details=specialMonthlyText;
                 							specialBD.Quantity=specialEmployeeCount;
                 							specialBD.Account=accountVal;
                 							specialBD.Current_Site=siteVal;
                 							specialBD.Source=siteVal;
                 							bill_record_ready = true;
                 							break;
                 						}
                 					}
                 				}
                 			}
                 		}
                 	}
                 	syncResponse.put("bill_record_ready",bill_record_ready);
                 	if(voucherRecord.ID == null)
                 	{
                 		syncResponse.put("message","Voucher Register record was not found.");
                 	}
                 	else if(voucherRecord.Employee == null)
                 	{
                 		syncResponse.put("message","The voucher has no employee.");
                 	}
                 	else
                 	{
                 		syncResponse.put("ok",true);
                 		syncResponse.put("message","Employee billing synchronized successfully.");
                 		syncResponse.put("voucher_id",voucher_id);
                 	}
                 	return syncResponse;
                 }

void customer.update_customer_performance(int customer_id)
{
                 	if(customer_id == null)
                 	{
                 		return;
                 	}
                 	customer_rec = Customer_Register[ID == customer_id];
                 	if(customer_rec.ID == null)
                 	{
                 		return;
                 	}
                 	valid_sales = Sales_Voucher[Customer == customer_id && Cancel_Voucher != true && Payment_Status != "Cancelled"];
                 	total_sales_orders = valid_sales.count();
                 	total_revenue = ifnull(valid_sales.sum(Grand_Total),0.0);
                 	last_purchase_date = valid_sales.maximum(Sales_Voucher_Date);
                 	valid_payments = Payment_Receipt_Voucher[Customer == customer_id && Payment_Receipt_Voucher_Status != "Cancelled"];
                 	total_paid = ifnull(valid_payments.sum(Total_Amount_Received),0.0);
                 	credit_sales = Sales_Voucher[Customer == customer_id && Payment_Status == "Credit" && Cancel_Voucher != true];
                 	outstanding_balance = ifnull(credit_sales.sum(Grand_Total),0.0);
                 	if(outstanding_balance < 0)
                 	{
                 		outstanding_balance = 0.0;
                 	}
                 	credit_limit = ifnull(customer_rec.Credit_Limit,0.0);
                 	available_credit = credit_limit - outstanding_balance;
                 	if(available_credit < 0)
                 	{
                 		available_credit = 0.0;
                 	}
                 	credit_status = "Not Applicable";
                 	if(ifnull(customer_rec.Customer_Type,"") == "Credit")
                 	{
                 		if(customer_rec.Credit_Allowed != true)
                 		{
                 			credit_status = "On Hold";
                 		}
                 		else if(credit_limit > 0 && outstanding_balance >= credit_limit)
                 		{
                 			credit_status = "Limit Reached";
                 		}
                 		else
                 		{
                 			credit_status = "Good Standing";
                 		}
                 	}
                 	customer_rec.Total_Sales_Orders=total_sales_orders;
                 	customer_rec.Total_Revenue=total_revenue;
                 	customer_rec.Total_Paid=total_paid;
                 	customer_rec.Outstanding_Balance=outstanding_balance;
                 	customer_rec.Current_Outstanding_Balance=outstanding_balance;
                 	customer_rec.Last_Purchase_Date=last_purchase_date;
                 	customer_rec.Available_Credit=available_credit;
                 	customer_rec.Credit_Status=credit_status;
                 }

map labour.recalculate_truck_movement_labour(int employee_id, string employee_display_name, date work_date)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("employee_id",employee_id);
                 	result.put("employee",employee_display_name);
                 	result.put("monthly_salary",0.0);
                 	result.put("working_days",0);
                 	result.put("daily_labour",0.0);
                 	result.put("trip_lines_updated",0);
                 	result.put("calculated_labour_total",0.0);
                 	if(employee_id == null)
                 	{
                 		result.put("message","Employee ID is required.");
                 		return result;
                 	}
                 	employee_display_name = ifnull(employee_display_name,"").trim();
                 	if(work_date == null)
                 	{
                 		work_date = zoho.currentdate;
                 	}
                 	salary_result = employee_management.employee.get_employee_salary_details(employee_id,work_date);
                 	if(salary_result == null)
                 	{
                 		result.put("message","Employee Management returned no salary information.");
                 		return result;
                 	}
                 	if(ifnull(salary_result.get("ok"),false) != true)
                 	{
                 		result.put("message",ifnull(salary_result.get("message"),"Employee salary could not be retrieved."));
                 		return result;
                 	}
                 	monthly_salary = ifnull(salary_result.get("monthly_salary"),0.0);
                 	if(monthly_salary <= 0)
                 	{
                 		result.put("message","The employee monthly salary must be greater than zero.");
                 		return result;
                 	}
                 	result.put("monthly_salary",monthly_salary);
                 	month_number = work_date.getMonth();
                 	year_number = work_date.getYear();
                 	month_text = month_number.toString();
                 	if(month_number < 10)
                 	{
                 		month_text = "0" + month_number;
                 	}
                 	month_start_text = "01-" + month_text + "-" + year_number.toString();
                 	month_start = month_start_text.toDate("dd-MM-yyyy");
                 	next_month_start = month_start.addMonth(1);
                 	result.put("month_start",month_start);
                 	result.put("next_month_start",next_month_start);
                 	month_trips = Truck_Movement_Voucher[Voucher.Employee == employee_id && Time_Start >= month_start && Time_Start < next_month_start && Cancel_Voucher != true];
                 	if(month_trips.count() <= 0)
                 	{
                 		result.put("message","No truck movements were found for the employee in this month.");
                 		return result;
                 	}
                 	trips_per_day = Map();
                 	working_dates = List();
                 	for each  trip_rec in month_trips
                 	{
                 		if(trip_rec.Time_Start != null)
                 		{
                 			movement_date = trip_rec.Time_Start.toDate();
                 			day_key = movement_date.toString("yyyy-MM-dd");
                 			if(!working_dates.contains(day_key))
                 			{
                 				working_dates.add(day_key);
                 			}
                 			day_trip_count = 0;
                 			if(trips_per_day.containKey(day_key))
                 			{
                 				day_trip_count = ifnull(trips_per_day.get(day_key),0);
                 			}
                 			trips_per_day.put(day_key,day_trip_count + 1);
                 		}
                 	}
                 	working_days = working_dates.size();
                 	if(working_days <= 0)
                 	{
                 		result.put("message","No valid working dates were found.");
                 		return result;
                 	}
                 	daily_labour = round(monthly_salary / working_days,2);
                 	result.put("working_days",working_days);
                 	result.put("daily_labour",daily_labour);
                 	updated_count = 0;
                 	calculated_total = 0.0;
                 	for each  trip_rec in month_trips
                 	{
                 		if(trip_rec.Time_Start != null)
                 		{
                 			day_key = trip_rec.Time_Start.toDate().toString("yyyy-MM-dd");
                 			trips_that_day = ifnull(trips_per_day.get(day_key),0);
                 			if(trips_that_day > 0)
                 			{
                 				labour_per_trip = round(daily_labour / trips_that_day,2);
                 				trip_rec.Labour_Cost=labour_per_trip;
                 				calculated_total = calculated_total + labour_per_trip;
                 				updated_count = updated_count + 1;
                 			}
                 		}
                 	}
                 	result.put("trip_lines_updated",updated_count);
                 	result.put("calculated_labour_total",round(calculated_total,2));
                 	result.put("ok",true);
                 	result.put("message","Truck movement labour was recalculated successfully.");
                 	return result;
                 }

map lease.generateDueRentInvoices(bigint lease_id)
{
                 	// =====================================================
                 	// GENERATE DUE RENT INVOICES FOR ONE LEASE
                 	// =====================================================
                 	response = Map();
                 	response.put("ok",false);
                 	response.put("message","");
                 	response.put("created_invoices",0);
                 	response.put("updated_invoices",0);
                 	response.put("created_details",0);
                 	response.put("updated_details",0);
                 	response.put("business_syncs",0);
                 	response.put("asset_syncs",0);
                 	response.put("skipped_count",0);
                 	created_invoices = 0;
                 	updated_invoices = 0;
                 	created_details = 0;
                 	updated_details = 0;
                 	business_syncs = 0;
                 	asset_syncs = 0;
                 	skipped_count = 0;
                 	today_date = zoho.currentdate;
                 	period_loop_text = leftpad("",240);
                 	period_loop_text = period_loop_text.replaceAll(" ",",");
                 	period_loop = period_loop_text.toList(",");
                 	// =====================================================
                 	// 1. FIND LEASE
                 	// =====================================================
                 	lease_rec = Lease_Register[ID == lease_id];
                 	if(lease_rec.ID == null)
                 	{
                 		response.put("message","Lease record was not found for ID: " + lease_id);
                 		return response;
                 	}
                 	// =====================================================
                 	// 2. VALIDATE LEASE STATUS
                 	// =====================================================
                 	if(ifnull(lease_rec.Lease_Status,"").trim() != "Active")
                 	{
                 		response.put("message","Rent invoices were not generated because Lease " + ifnull(lease_rec.Lease_Number,"") + " is not Active. Current status: " + ifnull(lease_rec.Lease_Status,"Not Defined"));
                 		return response;
                 	}
                 	// =====================================================
                 	// 3. NON-CHARGEABLE OCCUPANCY
                 	// Payment Frequency = None
                 	// =====================================================
                 	if(ifnull(lease_rec.Payment_Frequency,"").trim() == "None")
                 	{
                 		response.put("ok",true);
                 		response.put("message","Lease " + ifnull(lease_rec.Lease_Number,"") + " is non-chargeable. No Invoice or Invoice Detail was generated.");
                 		return response;
                 	}
                 	// =====================================================
                 	// 4. VALIDATE REQUIRED INFORMATION
                 	// =====================================================
                 	if(lease_rec.Lease_Start_Date == null)
                 	{
                 		response.put("message","Lease Start Date is required.");
                 		return response;
                 	}
                 	if(lease_rec.Lease_End_Date == null)
                 	{
                 		response.put("message","Lease End Date is required.");
                 		return response;
                 	}
                 	if(lease_rec.Lease_Number == null || lease_rec.Lease_Number.trim() == "")
                 	{
                 		response.put("message","Lease Number is required.");
                 		return response;
                 	}
                 	if(lease_rec.Customer == null)
                 	{
                 		response.put("message","Customer is required.");
                 		return response;
                 	}
                 	if(lease_rec.Agreed_Monthly_Rent == null || lease_rec.Agreed_Monthly_Rent <= 0)
                 	{
                 		response.put("message","Agreed Monthly Rent must be greater than zero.");
                 		return response;
                 	}
                 	if(lease_rec.Payment_Frequency == null || lease_rec.Payment_Frequency.trim() == "")
                 	{
                 		response.put("message","Payment Frequency is required.");
                 		return response;
                 	}
                 	if(lease_rec.Lease_End_Date < lease_rec.Lease_Start_Date)
                 	{
                 		response.put("message","Lease End Date cannot be before Lease Start Date.");
                 		return response;
                 	}
                 	if(today_date < lease_rec.Lease_Start_Date)
                 	{
                 		response.put("ok",true);
                 		response.put("message","No rent Invoice is due because the Lease starts on " + lease_rec.Lease_Start_Date.toString("dd-MMM-yyyy") + ".");
                 		return response;
                 	}
                 	// =====================================================
                 	// 5. COMMON VALUES
                 	// =====================================================
                 	site_text = "";
                 	account_text = "";
                 	if(lease_rec.Asset != null)
                 	{
                 		site_text = ifnull(lease_rec.Asset.Current_Site,"").trim();
                 		account_text = ifnull(lease_rec.Asset.Current_Site,"").trim();
                 	}
                 	asset_text = ifnull(lease_rec.Display_Name_Asset,"").trim();
                 	building_text = ifnull(lease_rec.Display_Name_Building,"").trim();
                 	permitted_use_text = ifnull(lease_rec.Display_Name_Permitted_Use,"").trim();
                 	business_text = ifnull(lease_rec.Business_Name,"").trim();
                 	customer_text = ifnull(lease_rec.Display_Name_Customer,"").trim();
                 	start_date = lease_rec.Lease_Start_Date;
                 	end_date = lease_rec.Lease_End_Date;
                 	// =====================================================
                 	// 6. DETERMINE PAYMENT FREQUENCY
                 	// =====================================================
                 	frequency_months = 0;
                 	if(lease_rec.Payment_Frequency == "Monthly")
                 	{
                 		frequency_months = 1;
                 	}
                 	else if(lease_rec.Payment_Frequency == "Quarterly" || lease_rec.Payment_Frequency == "Quarterly (Every 3 Months)")
                 	{
                 		frequency_months = 3;
                 	}
                 	else if(lease_rec.Payment_Frequency == "Bi-Annually" || lease_rec.Payment_Frequency == "Semi-Annual" || lease_rec.Payment_Frequency == "Semi-Annual (Every 6 Months)")
                 	{
                 		frequency_months = 6;
                 	}
                 	else if(lease_rec.Payment_Frequency == "Annually" || lease_rec.Payment_Frequency == "Annual" || lease_rec.Payment_Frequency == "Annual (Yearly)")
                 	{
                 		frequency_months = 12;
                 	}
                 	if(frequency_months <= 0)
                 	{
                 		response.put("message","Unsupported Payment Frequency: " + lease_rec.Payment_Frequency);
                 		return response;
                 	}
                 	// =====================================================
                 	// 7. START-MONTH DATES
                 	// =====================================================
                 	month_start_text = "01-" + start_date.toString("MM-yyyy");
                 	start_month_first_day = month_start_text.toDate("dd-MM-yyyy");
                 	next_month_first_day = start_month_first_day.addMonth(1);
                 	start_month_last_day = next_month_first_day.addDay(-1);
                 	days_in_start_month = start_month_first_day.daysBetween(next_month_first_day);
                 	occupied_days = start_date.daysBetween(next_month_first_day);
                 	last_processed_invoice_date = null;
                 	// =====================================================
                 	// 8. PRORATED FIRST MONTH
                 	// =====================================================
                 	if(start_date.getDay() > 1 && start_date <= today_date)
                 	{
                 		prorated_rate = round((ifnull(lease_rec.Agreed_Monthly_Rent,0.0) * occupied_days) / days_in_start_month,2);
                 		prorated_quantity = 1;
                 		prorated_line_total = prorated_rate;
                 		prorated_item = "";
                 		if(asset_text != "")
                 		{
                 			prorated_item = "Asset: " + asset_text;
                 		}
                 		if(building_text != "")
                 		{
                 			if(prorated_item != "")
                 			{
                 				prorated_item = prorated_item + "\n";
                 			}
                 			prorated_item = prorated_item + "Building: " + building_text;
                 		}
                 		if(prorated_item != "")
                 		{
                 			prorated_item = prorated_item + "\n";
                 		}
                 		prorated_item = prorated_item + "Charge Type: Prorated Rent";
                 		prorated_period_text = "Billing Period: " + start_date.toString("dd-MMM-yyyy") + " to " + start_month_last_day.toString("dd-MMM-yyyy");
                 		prorated_invoice_number = "Rent - " + start_date.toString("yyyy-MM") + " - " + asset_text;
                 		prorated_details = "Business Name: " + business_text + "\n";
                 		prorated_details = prorated_details + "Tenant: " + customer_text + "\n";
                 		prorated_details = prorated_details + "Lease Number: " + lease_rec.Lease_Number + "\n";
                 		prorated_details = prorated_details + "Asset: " + asset_text + "\n";
                 		prorated_details = prorated_details + "Permitted Use: " + permitted_use_text + "\n";
                 		prorated_details = prorated_details + "Charge Type: Prorated Rent\n";
                 		prorated_details = prorated_details + prorated_period_text + "\n";
                 		prorated_details = prorated_details + "Days Occupied: " + occupied_days + "\n";
                 		prorated_details = prorated_details + "Days in Month: " + days_in_start_month + "\n";
                 		prorated_details = prorated_details + "Monthly Rent: " + lease_rec.Agreed_Monthly_Rent + "\n";
                 		prorated_details = prorated_details + "Payment Frequency: " + lease_rec.Payment_Frequency;
                 		existing_prorated = Invoice_Details[Source_Record_ID == lease_rec.ID && Source_Form == "Lease Register" && Details.contains("Charge Type: Prorated Rent") && Details.contains(prorated_period_text)];
                 		prorated_invoice_id = null;
                 		prorated_detail_id = null;
                 		prorated_can_sync = false;
                 		if(existing_prorated.ID != null)
                 		{
                 			prorated_detail_id = existing_prorated.ID;
                 			if(existing_prorated.Invoice != null)
                 			{
                 				prorated_invoice_id = existing_prorated.Invoice;
                 			}
                 		}
                 		prorated_is_editable = false;
                 		if(existing_prorated.ID == null)
                 		{
                 			prorated_is_editable = true;
                 		}
                 		else if(existing_prorated.Invoice_Details_Status == null || existing_prorated.Invoice_Details_Status == "" || existing_prorated.Invoice_Details_Status == "Draft")
                 		{
                 			prorated_is_editable = true;
                 		}
                 		else
                 		{
                 			skipped_count = skipped_count + 1;
                 		}
                 		if(prorated_is_editable == true)
                 		{
                 			if(prorated_invoice_id == null)
                 			{
                 				prorated_invoice_id = insert into Invoice
                 				[
                 					Invoice_Date=start_date
                 					Invoice_Number=prorated_invoice_number
                 					Customer=lease_rec.Customer
                 					Display_Name_Customer=customer_text
                 					Sub_Total=prorated_line_total
                 					Discount_Type="None"
                 					Discount_Percentage=0.0
                 					Discount_Amount=0.0
                 					Tax_Amount=0.0
                 					Grand_Total=prorated_line_total
                 					Amount_Paid=0.0
                 					Balance_Due=prorated_line_total
                 					Invoice_Status="Draft"
                 					Payment_Status="Not Paid"
                 					Added_User=zoho.loginuser
                 				];
                 				if(prorated_invoice_id != null)
                 				{
                 					created_invoices = created_invoices + 1;
                 				}
                 			}
                 			if(existing_prorated.ID == null && prorated_invoice_id != null)
                 			{
                 				prorated_invoice_rec = Invoice[ID == prorated_invoice_id];
                 				prorated_detail_id = insert into Invoice_Details
                 				[
                 					Invoice=prorated_invoice_id
                 					Display_Name_Invoice=prorated_invoice_rec.Invoice_Number
                 					Lease=lease_rec.ID
                 					Display_Name_Voucher=lease_rec.Lease_Number
                 					Details_Date=start_date
                 					Invoice_Details_Status="Invoiced"
                 					Line_Number=1
                 					Item=prorated_item
                 					Details=prorated_details
                 					Quantity=prorated_quantity
                 					Rate=prorated_rate
                 					Site=site_text
                 					Account=account_text
                 					Source_Record_ID=lease_rec.ID
                 					Source_Form="Lease Register"
                 					Added_User=zoho.loginuser
                 				];
                 				if(prorated_detail_id != null)
                 				{
                 					created_details = created_details + 1;
                 					prorated_can_sync = true;
                 					last_processed_invoice_date = start_date;
                 				}
                 			}
                 			else if(existing_prorated.ID != null && prorated_invoice_id != null)
                 			{
                 				prorated_invoice_rec = Invoice[ID == prorated_invoice_id];
                 				existing_prorated.Invoice=prorated_invoice_id;
                 				existing_prorated.Display_Name_Invoice=prorated_invoice_rec.Invoice_Number;
                 				existing_prorated.Lease=lease_rec.ID;
                 				existing_prorated.Display_Name_Voucher=lease_rec.Lease_Number;
                 				existing_prorated.Details_Date=start_date;
                 				existing_prorated.Invoice_Details_Status="Invoiced";
                 				existing_prorated.Line_Number=1;
                 				existing_prorated.Item=prorated_item;
                 				existing_prorated.Details=prorated_details;
                 				existing_prorated.Quantity=prorated_quantity;
                 				existing_prorated.Rate=prorated_rate;
                 				existing_prorated.Site=site_text;
                 				existing_prorated.Account=account_text;
                 				existing_prorated.Source_Record_ID=lease_rec.ID;
                 				existing_prorated.Source_Form="Lease Register";
                 				updated_details = updated_details + 1;
                 				prorated_can_sync = true;
                 				last_processed_invoice_date = start_date;
                 			}
                 			if(prorated_invoice_id != null)
                 			{
                 				prorated_invoice_rec = Invoice[ID == prorated_invoice_id];
                 				if(prorated_invoice_rec.ID != null)
                 				{
                 					prorated_invoice_rec.Invoice_Date=start_date;
                 					prorated_invoice_rec.Invoice_Number=prorated_invoice_number;
                 					prorated_invoice_rec.Customer=lease_rec.Customer;
                 					prorated_invoice_rec.Display_Name_Customer=customer_text;
                 					prorated_invoice_rec.Sub_Total=prorated_line_total;
                 					prorated_invoice_rec.Discount_Type="None";
                 					prorated_invoice_rec.Discount_Percentage=0.0;
                 					prorated_invoice_rec.Discount_Amount=0.0;
                 					prorated_invoice_rec.Tax_Amount=0.0;
                 					prorated_invoice_rec.Grand_Total=prorated_line_total;
                 					prorated_invoice_rec.Amount_Paid=0.0;
                 					prorated_invoice_rec.Balance_Due=prorated_line_total;
                 					prorated_invoice_rec.Invoice_Status="Draft";
                 					prorated_invoice_rec.Payment_Status="Not Paid";
                 					updated_invoices = updated_invoices + 1;
                 				}
                 			}
                 			if(prorated_can_sync == true && prorated_detail_id != null && prorated_invoice_id != null)
                 			{
                 				post = Map();
                 				post.put("Display_Name_Application","Crown Plaza Management");
                 				post.put("Source_Form","Invoice Details");
                 				post.put("Source_Record_ID",prorated_detail_id.toString());
                 				post.put("FCM_Invoice_Details",prorated_detail_id);
                 				post.put("Voucher_Number",prorated_invoice_number);
                 				post.put("Transaction_Date",start_date);
                 				post.put("Business_Division",null);
                 				post.put("Display_Name_Business_Division","");
                 				post.put("Amount_To_Receive",prorated_line_total);
                 				post.put("Amount_Received",0.0);
                 				post.put("Amount_Not_Received",prorated_line_total);
                 				post.put("Amount_To_Pay",0.0);
                 				post.put("Amount_Paid",0.0);
                 				post.put("Amount_Not_Paid",0.0);
                 				business_response = grapes_group.freedomcity.postBusinessDivisionDetail(post);
                 				info business_response;
                 				business_syncs = business_syncs + 1;
                 			}
                 			// ---------------------------------------------
                 			// Asset Transaction sync
                 			// ---------------------------------------------
                 			if(prorated_can_sync == true && prorated_detail_id != null && prorated_invoice_id != null && prorated_line_total > 0 && lease_rec.Asset != null)
                 			{
                 				transaction_description = "Invoice " + prorated_invoice_number + " - Line 1 - " + prorated_details;
                 				asset_payload = Map();
                 				asset_payload.put("Transaction_Date",start_date);
                 				asset_payload.put("Transaction_Status","Posted");
                 				asset_payload.put("Transaction_Description",transaction_description);
                 				asset_payload.put("Asset",lease_rec.Asset);
                 				asset_payload.put("Display_Name_Asset",asset_text);
                 				asset_payload.put("Transaction_Direction","Income");
                 				asset_payload.put("Amount",prorated_line_total);
                 				asset_payload.put("Income",prorated_line_total);
                 				asset_payload.put("Expenses",0.0);
                 				asset_payload.put("Application","Crown Plaza Management");
                 				asset_payload.put("Source_Form","Invoice Details");
                 				asset_payload.put("Source_Record_ID",prorated_detail_id);
                 				asset_payload.put("Notes","Generated from Lease " + lease_rec.Lease_Number + ". Invoice Detail ID: " + prorated_detail_id);
                 				asset_response = asset_management.createOrUpdateAssetTransactionLog(asset_payload);
                 				info asset_response;
                 				asset_syncs = asset_syncs + 1;
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 9. FIRST REGULAR BILLING PERIOD
                 	// =====================================================
                 	if(start_date.getDay() == 1)
                 	{
                 		regular_period_start = start_month_first_day;
                 	}
                 	else
                 	{
                 		regular_period_start = next_month_first_day;
                 	}
                 	// =====================================================
                 	// 10. CREATE OR UPDATE REGULAR PERIODS
                 	// =====================================================
                 	for each  period_slot in period_loop
                 	{
                 		if(regular_period_start > end_date)
                 		{
                 			break;
                 		}
                 		if(regular_period_start > today_date)
                 		{
                 			break;
                 		}
                 		period_start = regular_period_start;
                 		period_end = period_start.addMonth(frequency_months).addDay(-1);
                 		if(period_end > end_date)
                 		{
                 			period_end = end_date;
                 		}
                 		// -------------------------------------------------
                 		// Rate = monthly rent
                 		// Quantity = frequency months
                 		// -------------------------------------------------
                 		invoice_rate = round(ifnull(lease_rec.Agreed_Monthly_Rent,0.0),2);
                 		invoice_quantity = frequency_months;
                 		invoice_line_total = round(invoice_rate * invoice_quantity,2);
                 		// -------------------------------------------------
                 		// Item
                 		// -------------------------------------------------
                 		rent_item = "";
                 		if(asset_text != "")
                 		{
                 			rent_item = "Asset: " + asset_text;
                 		}
                 		if(building_text != "")
                 		{
                 			if(rent_item != "")
                 			{
                 				rent_item = rent_item + "\n";
                 			}
                 			rent_item = rent_item + "Building: " + building_text;
                 		}
                 		if(rent_item != "")
                 		{
                 			rent_item = rent_item + "\n";
                 		}
                 		rent_item = rent_item + "Charge Type: Regular Rent";
                 		// -------------------------------------------------
                 		// Billing period
                 		// -------------------------------------------------
                 		billing_period_text = "Billing Period: " + period_start.toString("dd-MMM-yyyy") + " to " + period_end.toString("dd-MMM-yyyy");
                 		// -------------------------------------------------
                 		// Invoice Number
                 		// -------------------------------------------------
                 		if(frequency_months == 1)
                 		{
                 			invoice_number_text = "Rent - " + period_start.toString("yyyy-MM") + " - " + asset_text;
                 		}
                 		else
                 		{
                 			invoice_number_text = "Rent - " + period_start.toString("yyyy-MM") + " to " + period_end.toString("yyyy-MM") + " - " + asset_text;
                 		}
                 		// -------------------------------------------------
                 		// Details
                 		// -------------------------------------------------
                 		details_text = "Business Name: " + business_text + "\n";
                 		details_text = details_text + "Tenant: " + customer_text + "\n";
                 		details_text = details_text + "Lease Number: " + lease_rec.Lease_Number + "\n";
                 		details_text = details_text + "Asset: " + asset_text + "\n";
                 		details_text = details_text + "Permitted Use: " + permitted_use_text + "\n";
                 		details_text = details_text + "Charge Type: Regular Rent\n";
                 		details_text = details_text + billing_period_text + "\n";
                 		details_text = details_text + "Payment Frequency: " + lease_rec.Payment_Frequency + "\n";
                 		details_text = details_text + "Monthly Rent: " + invoice_rate + "\n";
                 		details_text = details_text + "Number of Months: " + invoice_quantity;
                 		// -------------------------------------------------
                 		// Find existing Detail
                 		// -------------------------------------------------
                 		existing_regular = Invoice_Details[Source_Record_ID == lease_rec.ID && Source_Form == "Lease Register" && Details.contains("Charge Type: Regular Rent") && Details.contains(billing_period_text)];
                 		invoice_id = null;
                 		invoice_detail_id = null;
                 		detail_can_sync = false;
                 		if(existing_regular.ID != null)
                 		{
                 			invoice_detail_id = existing_regular.ID;
                 			if(existing_regular.Invoice != null)
                 			{
                 				invoice_id = existing_regular.Invoice;
                 			}
                 		}
                 		// -------------------------------------------------
                 		// Preserve non-Draft details
                 		// -------------------------------------------------
                 		detail_is_editable = false;
                 		if(existing_regular.ID == null)
                 		{
                 			detail_is_editable = true;
                 		}
                 		else if(existing_regular.Invoice_Details_Status == null || existing_regular.Invoice_Details_Status == "" || existing_regular.Invoice_Details_Status == "Draft")
                 		{
                 			detail_is_editable = true;
                 		}
                 		else
                 		{
                 			skipped_count = skipped_count + 1;
                 			last_processed_invoice_date = period_start;
                 		}
                 		if(detail_is_editable == true)
                 		{
                 			// ---------------------------------------------
                 			// Create missing Invoice
                 			// ---------------------------------------------
                 			if(invoice_id == null)
                 			{
                 				invoice_id = insert into Invoice
                 				[
                 					Invoice_Date=period_start
                 					Invoice_Number=invoice_number_text
                 					Customer=lease_rec.Customer
                 					Display_Name_Customer=customer_text
                 					Sub_Total=invoice_line_total
                 					Discount_Type="None"
                 					Discount_Percentage=0.0
                 					Discount_Amount=0.0
                 					Tax_Amount=0.0
                 					Grand_Total=invoice_line_total
                 					Amount_Paid=0.0
                 					Balance_Due=invoice_line_total
                 					Invoice_Status="Draft"
                 					Payment_Status="Not Paid"
                 					Added_User=zoho.loginuser
                 				];
                 				if(invoice_id != null)
                 				{
                 					created_invoices = created_invoices + 1;
                 				}
                 			}
                 			// ---------------------------------------------
                 			// Create missing Invoice Detail
                 			// ---------------------------------------------
                 			if(existing_regular.ID == null && invoice_id != null)
                 			{
                 				invoice_rec = Invoice[ID == invoice_id];
                 				invoice_detail_id = insert into Invoice_Details
                 				[
                 					Invoice=invoice_id
                 					Display_Name_Invoice=invoice_rec.Invoice_Number
                 					Lease=lease_rec.ID
                 					Display_Name_Voucher=lease_rec.Lease_Number
                 					Details_Date=period_start
                 					Invoice_Details_Status="Invoiced"
                 					Line_Number=1
                 					Item=rent_item
                 					Details=details_text
                 					Quantity=invoice_quantity
                 					Rate=invoice_rate
                 					Site=site_text
                 					Account=account_text
                 					Source_Record_ID=lease_rec.ID
                 					Source_Form="Lease Register"
                 					Added_User=zoho.loginuser
                 				];
                 				if(invoice_detail_id != null)
                 				{
                 					created_details = created_details + 1;
                 					detail_can_sync = true;
                 					last_processed_invoice_date = period_start;
                 				}
                 			}
                 			else if(existing_regular.ID != null && invoice_id != null)
                 			{
                 				invoice_rec = Invoice[ID == invoice_id];
                 				existing_regular.Invoice=invoice_id;
                 				existing_regular.Display_Name_Invoice=invoice_rec.Invoice_Number;
                 				existing_regular.Lease=lease_rec.ID;
                 				existing_regular.Display_Name_Voucher=lease_rec.Lease_Number;
                 				existing_regular.Details_Date=period_start;
                 				existing_regular.Invoice_Details_Status="Invoiced";
                 				existing_regular.Line_Number=1;
                 				existing_regular.Item=rent_item;
                 				existing_regular.Details=details_text;
                 				existing_regular.Quantity=invoice_quantity;
                 				existing_regular.Rate=invoice_rate;
                 				existing_regular.Site=site_text;
                 				existing_regular.Account=account_text;
                 				existing_regular.Source_Record_ID=lease_rec.ID;
                 				existing_regular.Source_Form="Lease Register";
                 				updated_details = updated_details + 1;
                 				detail_can_sync = true;
                 				last_processed_invoice_date = period_start;
                 			}
                 			// ---------------------------------------------
                 			// Refresh Draft Invoice header
                 			// ---------------------------------------------
                 			if(invoice_id != null)
                 			{
                 				invoice_rec = Invoice[ID == invoice_id];
                 				if(invoice_rec.ID != null)
                 				{
                 					invoice_rec.Invoice_Date=period_start;
                 					invoice_rec.Invoice_Number=invoice_number_text;
                 					invoice_rec.Customer=lease_rec.Customer;
                 					invoice_rec.Display_Name_Customer=customer_text;
                 					invoice_rec.Sub_Total=invoice_line_total;
                 					invoice_rec.Discount_Type="None";
                 					invoice_rec.Discount_Percentage=0.0;
                 					invoice_rec.Discount_Amount=0.0;
                 					invoice_rec.Tax_Amount=0.0;
                 					invoice_rec.Grand_Total=invoice_line_total;
                 					invoice_rec.Amount_Paid=0.0;
                 					invoice_rec.Balance_Due=invoice_line_total;
                 					invoice_rec.Invoice_Status="Draft";
                 					invoice_rec.Payment_Status="Not Paid";
                 					updated_invoices = updated_invoices + 1;
                 				}
                 			}
                 			// ---------------------------------------------
                 			// Business Division sync
                 			// ---------------------------------------------
                 			if(detail_can_sync == true && invoice_detail_id != null && invoice_id != null)
                 			{
                 				post = Map();
                 				post.put("Display_Name_Application","Crown Plaza Management");
                 				post.put("Source_Form","Invoice Details");
                 				post.put("Source_Record_ID",invoice_detail_id.toString());
                 				post.put("FCM_Invoice_Details",invoice_detail_id);
                 				post.put("Voucher_Number",invoice_number_text);
                 				post.put("Transaction_Date",period_start);
                 				post.put("Business_Division",null);
                 				post.put("Display_Name_Business_Division","");
                 				post.put("Amount_To_Receive",invoice_line_total);
                 				post.put("Amount_Received",0.0);
                 				post.put("Amount_Not_Received",invoice_line_total);
                 				post.put("Amount_To_Pay",0.0);
                 				post.put("Amount_Paid",0.0);
                 				post.put("Amount_Not_Paid",0.0);
                 				business_response = grapes_group.freedomcity.postBusinessDivisionDetail(post);
                 				info business_response;
                 				business_syncs = business_syncs + 1;
                 			}
                 			// ---------------------------------------------
                 			// Asset Transaction sync
                 			// ---------------------------------------------
                 			if(detail_can_sync == true && invoice_detail_id != null && invoice_id != null && invoice_line_total > 0 && lease_rec.Asset != null)
                 			{
                 				transaction_description = "Invoice " + invoice_number_text + " - Line 1 - " + details_text;
                 				asset_payload = Map();
                 				asset_payload.put("Transaction_Date",period_start);
                 				asset_payload.put("Transaction_Status","Posted");
                 				asset_payload.put("Transaction_Description",transaction_description);
                 				asset_payload.put("Asset",lease_rec.Asset);
                 				asset_payload.put("Display_Name_Asset",asset_text);
                 				asset_payload.put("Transaction_Direction","Income");
                 				asset_payload.put("Amount",invoice_line_total);
                 				asset_payload.put("Income",invoice_line_total);
                 				asset_payload.put("Expenses",0.0);
                 				asset_payload.put("Application","Crown Plaza Management");
                 				asset_payload.put("Source_Form","Invoice Details");
                 				asset_payload.put("Source_Record_ID",invoice_detail_id);
                 				asset_payload.put("Notes","Generated from Lease " + lease_rec.Lease_Number + ". Invoice Detail ID: " + invoice_detail_id);
                 				asset_response = asset_management.createOrUpdateAssetTransactionLog(asset_payload);
                 				info asset_response;
                 				asset_syncs = asset_syncs + 1;
                 			}
                 		}
                 		regular_period_start = regular_period_start.addMonth(frequency_months);
                 	}
                 	// =====================================================
                 	// 11. UPDATE LAST INVOICE DATE
                 	// =====================================================
                 	if(last_processed_invoice_date != null)
                 	{
                 		lease_rec.Last_Invoice_Date=last_processed_invoice_date;
                 	}
                 	// =====================================================
                 	// 12. RETURN RESPONSE
                 	// =====================================================
                 	response.put("ok",true);
                 	response.put("created_invoices",created_invoices);
                 	response.put("updated_invoices",updated_invoices);
                 	response.put("created_details",created_details);
                 	response.put("updated_details",updated_details);
                 	response.put("business_syncs",business_syncs);
                 	response.put("asset_syncs",asset_syncs);
                 	response.put("skipped_count",skipped_count);
                 	response.put("message","Rent Invoice generation completed for " + lease_rec.Lease_Number + ". Invoices created: " + created_invoices + ", Invoices updated: " + updated_invoices + ", Details created: " + created_details + ", Details updated: " + updated_details + ", Preserved: " + skipped_count + ".");
                 	return response;
                 }

map po.push_po_status_to_store(int po_id)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	if(po_id == null)
                 	{
                 		result.put("message","Purchase Order ID is required.");
                 		return result;
                 	}
                 	po_rec = Purchase_Order[ID == po_id];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Crown Plaza Purchase Order not found.");
                 		return result;
                 	}
                 	po_number = ifnull(po_rec.PO_Number,"").trim();
                 	employee_voucher = ifnull(po_rec.Employee_Voucher,"").trim();
                 	po_status = ifnull(po_rec.PO_Status,"").trim();
                 	if(po_number == "")
                 	{
                 		result.put("message","PO Number is missing.");
                 		return result;
                 	}
                 	if(po_rec.PO_Date == null)
                 	{
                 		result.put("message","PO Date is missing.");
                 		return result;
                 	}
                 	if(employee_voucher == "")
                 	{
                 		result.put("message","Employee Voucher is missing.");
                 		return result;
                 	}
                 	if(po_status == "")
                 	{
                 		result.put("message","PO Status is missing.");
                 		return result;
                 	}
                 	sync_resp = store_management.po.sync_po_status_from_concrete(po_number,po_rec.PO_Date,employee_voucher,po_status);
                 	return sync_resp;
                 }

map po.sync_po_status_from_store(string source_record_id_text, string po_status)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	source_record_id_text = ifnull(source_record_id_text,"").trim();
                 	po_status = ifnull(po_status,"").trim();
                 	if(source_record_id_text == "")
                 	{
                 		result.put("message","Source Record ID is required.");
                 		return result;
                 	}
                 	if(po_status == "")
                 	{
                 		result.put("message","PO Status is required.");
                 		return result;
                 	}
                 	source_record_id = source_record_id_text.toLong();
                 	po_rec = Purchase_Order[ID == source_record_id];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Crown Plaza Purchase Order not found for ID " + source_record_id_text);
                 		return result;
                 	}
                 	po_rec.PO_Status=po_status;
                 	result.put("ok",true);
                 	result.put("message","Crown Plaza Purchase Order status updated to " + po_status);
                 	return result;
                 }

void po.update_all_po_bill_status()
{
                 	po_list = Purchase_Order[ID != null];
                 	for each  po_rec in po_list
                 	{
                 		det_list = Purchase_Order_Details[Purchase_Order == po_rec.ID];
                 		has_lines = false;
                 		po_billed_total = 0.0;
                 		for each  det in det_list
                 		{
                 			has_lines = true;
                 			bill_rows = Bill_Details[Item == det.ID];
                 			for each  bd in bill_rows
                 			{
                 				po_billed_total = po_billed_total + ifnull(bd.Line_Total,0.0);
                 			}
                 		}
                 		po_rec.PO_Billed_Total=round(po_billed_total,2);
                 		po_total = round(ifnull(po_rec.PO_Total,0.0),2);
                 		if(has_lines == false || po_rec.PO_Billed_Total <= 0)
                 		{
                 			po_rec.Bill_Status="Not Billed";
                 		}
                 		else if(po_total > 0 && po_rec.PO_Billed_Total < po_total)
                 		{
                 			po_rec.Bill_Status="Partially Billed";
                 		}
                 		else
                 		{
                 			po_rec.Bill_Status="Billed";
                 		}
                 	}
                 }

void po.update_po_receiving_status(int po_id)
{
                 	if(po_id == null)
                 	{
                 		return;
                 	}
                 	po_rec = Purchase_Order[ID == po_id];
                 	if(po_rec.ID == null)
                 	{
                 		return;
                 	}
                 	det_list = Purchase_Order_Details[Purchase_Order == po_id];
                 	has_lines = false;
                 	any_received = false;
                 	all_fully_received = true;
                 	any_billed = false;
                 	all_fully_billed = true;
                 	po_billed_total = 0.0;
                 	po_total_paid = 0.0;
                 	related_bill_map = Map();
                 	for each  det in det_list
                 	{
                 		has_lines = true;
                 		rec_status = ifnull(det.Receiving_Status,"Not Received").trim();
                 		if(rec_status == "Fully Received" || rec_status == "Partially Received")
                 		{
                 			any_received = true;
                 		}
                 		if(rec_status != "Fully Received")
                 		{
                 			all_fully_received = false;
                 		}
                 		line_value = round(ifnull(det.Line_Total,0.0),2);
                 		if(line_value <= 0)
                 		{
                 			line_value = round(ifnull(det.Quantity_Ordered,0.0) * ifnull(det.Unit_Cost,0.0),2);
                 		}
                 		bill_status = ifnull(det.Billing_Status,"Not Billed").trim();
                 		if(line_value <= 0)
                 		{
                 			any_billed = true;
                 		}
                 		else
                 		{
                 			if(bill_status == "Fully Billed" || bill_status == "Partially Billed")
                 			{
                 				any_billed = true;
                 			}
                 			if(bill_status != "Fully Billed")
                 			{
                 				all_fully_billed = false;
                 			}
                 		}
                 	}
                 	if(has_lines == false)
                 	{
                 		po_rec.Receive_Status="Not Received";
                 		po_rec.Bill_Status="Not Billed";
                 		po_rec.PO_Billed_Total=0.0;
                 		po_rec.PO_Total_Paid=0.0;
                 		po_rec.Payment_Status="Not Paid";
                 		if(po_rec.PO_Status != "Cancelled")
                 		{
                 			po_rec.PO_Status="Open";
                 		}
                 		sync_resp = thisapp.po.push_po_status_to_store(po_rec.ID);
                 		info sync_resp;
                 		return;
                 	}
                 	if(all_fully_received == true)
                 	{
                 		po_rec.Receive_Status="Fully Received";
                 	}
                 	else if(any_received == true)
                 	{
                 		po_rec.Receive_Status="Partially Received";
                 	}
                 	else
                 	{
                 		po_rec.Receive_Status="Not Received";
                 	}
                 	if(all_fully_billed == true)
                 	{
                 		po_rec.Bill_Status="Billed";
                 	}
                 	else if(any_billed == true)
                 	{
                 		po_rec.Bill_Status="Partially Billed";
                 	}
                 	else
                 	{
                 		po_rec.Bill_Status="Not Billed";
                 	}
                 	po_bill_rows = Bill_Details[Item.Purchase_Order == po_rec.ID];
                 	for each  po_bd in po_bill_rows
                 	{
                 		po_line_total = round(ifnull(po_bd.Line_Total,0.0),2);
                 		po_billed_total = round(po_billed_total + po_line_total,2);
                 		if(po_bd.Bill != null)
                 		{
                 			bill_id = po_bd.Bill.ID;
                 			bill_key = bill_id.toString();
                 			if(related_bill_map.get(bill_key) == null)
                 			{
                 				related_bill_map.put(bill_key,bill_id);
                 			}
                 		}
                 	}
                 	po_rec.PO_Billed_Total=round(po_billed_total,2);
                 	for each  bill_key in related_bill_map.keys()
                 	{
                 		bill_id = related_bill_map.get(bill_key);
                 		bill_rec = Bill[ID == bill_id];
                 		if(bill_rec.ID != null)
                 		{
                 			bill_paid = round(ifnull(bill_rec.Amount_Paid,0.0),2);
                 			if(bill_paid > 0)
                 			{
                 				bill_po_lines_total = 0.0;
                 				this_po_bill_total = 0.0;
                 				all_bill_rows = Bill_Details[Bill == bill_id];
                 				for each  bill_line in all_bill_rows
                 				{
                 					line_total = round(ifnull(bill_line.Line_Total,0.0),2);
                 					if(bill_line.Item != null)
                 					{
                 						po_detail_rec = Purchase_Order_Details[ID == bill_line.Item.ID];
                 						if(po_detail_rec.ID != null && po_detail_rec.Purchase_Order != null)
                 						{
                 							bill_po_lines_total = round(bill_po_lines_total + line_total,2);
                 							if(po_detail_rec.Purchase_Order.ID == po_rec.ID)
                 							{
                 								this_po_bill_total = round(this_po_bill_total + line_total,2);
                 							}
                 						}
                 					}
                 				}
                 				if(bill_po_lines_total > 0 && this_po_bill_total > 0)
                 				{
                 					allocated_payment = round(bill_paid * this_po_bill_total / bill_po_lines_total,2);
                 					if(allocated_payment > this_po_bill_total)
                 					{
                 						allocated_payment = this_po_bill_total;
                 					}
                 					po_total_paid = round(po_total_paid + allocated_payment,2);
                 				}
                 			}
                 		}
                 	}
                 	po_rec.PO_Total_Paid=round(po_total_paid,2);
                 	po_total = round(ifnull(po_rec.PO_Total,0.0),2);
                 	if(po_total <= 0)
                 	{
                 		po_rec.Payment_Status="Not Payable";
                 	}
                 	else if(po_total_paid <= 0)
                 	{
                 		po_rec.Payment_Status="Not Paid";
                 	}
                 	else if(po_total_paid < po_total)
                 	{
                 		po_rec.Payment_Status="Partially Paid";
                 	}
                 	else
                 	{
                 		po_rec.Payment_Status="Paid";
                 	}
                 	if(po_rec.PO_Status != "Cancelled")
                 	{
                 		payment_complete = false;
                 		if(po_rec.Payment_Status == "Paid")
                 		{
                 			payment_complete = true;
                 		}
                 		else if(po_rec.Payment_Status == "Not Payable")
                 		{
                 			payment_complete = true;
                 		}
                 		if(all_fully_received == true && all_fully_billed == true && payment_complete == true)
                 		{
                 			po_rec.PO_Status="Closed";
                 		}
                 		else
                 		{
                 			po_rec.PO_Status="Open";
                 		}
                 	}
                 	sync_resp = thisapp.po.push_po_status_to_store(po_rec.ID);
                 	info sync_resp;
                 }

map services.recalculate_weekly_weigh_bridge(int employee_vendor_id, date work_date, string truck_plate)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("weekly_total",1000000.0);
                 	result.put("trip_count",0);
                 	result.put("rate_per_trip",0.0);
                 	result.put("lines_updated",0);
                 	result.put("bill_id",null);
                 	result.put("distributed_total",0.0);
                 	// =====================================================
                 	// 1. VALIDATE PARAMETERS
                 	// =====================================================
                 	if(employee_vendor_id == null)
                 	{
                 		result.put("message","Hamid Ssenoga employee vendor ID is required.");
                 		return result;
                 	}
                 	if(work_date == null)
                 	{
                 		work_date = zoho.currentdate;
                 	}
                 	truck_plate = ifnull(truck_plate,"").trim();
                 	if(truck_plate == "")
                 	{
                 		result.put("message","Number Plate - Truck Register is required.");
                 		return result;
                 	}
                 	weekly_total = 1000000.0;
                 	// =====================================================
                 	// 2. CALCULATE MONDAY TO NEXT MONDAY
                 	// =====================================================
                 	day_number = work_date.getDayOfWeek();
                 	if(day_number == 1)
                 	{
                 		// Sunday belongs to the week beginning six days earlier
                 		days_to_monday = -6;
                 	}
                 	else
                 	{
                 		days_to_monday = 2 - day_number;
                 	}
                 	week_start = work_date.addDay(days_to_monday);
                 	next_week_start = week_start.addDay(7);
                 	week_number = week_start.getWeekOfYear();
                 	week_text = week_number.toString();
                 	if(week_number < 10)
                 	{
                 		week_text = "0" + week_text;
                 	}
                 	week_identifier = week_start.getYear().toString() + " Week " + week_text;
                 	// Bill Number now identifies both truck and week
                 	weekly_bill_number = truck_plate + " - " + week_identifier;
                 	result.put("week_start",week_start);
                 	result.put("next_week_start",next_week_start);
                 	result.put("truck_plate",truck_plate);
                 	result.put("week_identifier",week_identifier);
                 	result.put("bill_number",weekly_bill_number);
                 	// =====================================================
                 	// 3. LOAD VALID MOVEMENTS FOR THIS TRUCK AND THIS WEEK
                 	// =====================================================
                 	week_movements = Truck_Movement_Voucher[Time_Start >= week_start && Time_Start < next_week_start && Number_Plate_Truck_Register == truck_plate && Cancel_Voucher != true && Truck_Movement_Voucher_Status != "Cancelled"];
                 	if(week_movements.count() <= 0)
                 	{
                 		result.put("message","No Truck Movement records were found for truck " + truck_plate + " in " + week_identifier + ".");
                 		return result;
                 	}
                 	// =====================================================
                 	// 4. COUNT WEIGH BRIDGE TRIPS FOR THIS TRUCK ONLY
                 	// =====================================================
                 	weigh_bridge_trip_count = 0;
                 	for each  movement_rec in week_movements
                 	{
                 		for each  srv in movement_rec.Services
                 		{
                 			if(srv.Service != null)
                 			{
                 				service_name = ifnull(srv.Service.Service_Name,"").trim();
                 				if(service_name == "Weigh Bridge")
                 				{
                 					weigh_bridge_trip_count = weigh_bridge_trip_count + 1;
                 				}
                 			}
                 		}
                 	}
                 	if(weigh_bridge_trip_count <= 0)
                 	{
                 		result.put("message","No Weigh Bridge service rows were found for truck " + truck_plate + " in " + week_identifier + ".");
                 		return result;
                 	}
                 	// =====================================================
                 	// 5. CALCULATE RATE PER TRIP
                 	// =====================================================
                 	rate_per_trip = round(weekly_total / weigh_bridge_trip_count,2);
                 	result.put("trip_count",weigh_bridge_trip_count);
                 	result.put("rate_per_trip",rate_per_trip);
                 	// =====================================================
                 	// 6. FIND EXISTING BILL FOR THIS TRUCK AND THIS WEEK
                 	// =====================================================
                 	weigh_bridge_bill = Bill[Employee_Vendor == employee_vendor_id && Bill_Name == "Weigh Bridge" && Bill_Number == weekly_bill_number && Bill_Type == "Employee Bill"];
                 	bill_id = null;
                 	if(weigh_bridge_bill.ID != null)
                 	{
                 		bill_id = weigh_bridge_bill.ID;
                 	}
                 	else
                 	{
                 		// =================================================
                 		// 7. CREATE A BILL FOR THIS TRUCK AND THIS WEEK
                 		// =================================================
                 		bill_id = insert into Bill
                 		[
                 			Bill_Date=week_start
                 			Bill_Type="Employee Bill"
                 			Employee_Vendor=employee_vendor_id
                 			Display_Name_Vendor="Hamid Ssenoga - 50"
                 			Bill_Name="Weigh Bridge"
                 			Bill_Number=weekly_bill_number
                 			Bill_Total=weekly_total
                 			Services_Total=weekly_total
                 			Total_Amount=weekly_total
                 			Amount_Due=weekly_total
                 			Amount_Paid=0.0
                 			Balance_Due=weekly_total
                 			Bill_Status="Draft"
                 			Payment_Status="Not Paid"
                 			Added_User=zoho.loginuser
                 		];
                 		if(bill_id != null)
                 		{
                 			weigh_bridge_bill = Bill[ID == bill_id];
                 		}
                 	}
                 	if(weigh_bridge_bill.ID == null)
                 	{
                 		result.put("message","The weekly Weigh Bridge Employee Bill for truck " + truck_plate + " could not be created.");
                 		return result;
                 	}
                 	// =====================================================
                 	// 8. KEEP THIS TRUCK'S WEEKLY BILL AT 1,000,000
                 	// =====================================================
                 	paid_amount = ifnull(weigh_bridge_bill.Amount_Paid,0.0);
                 	balance_amount = weekly_total - paid_amount;
                 	if(balance_amount < 0)
                 	{
                 		balance_amount = 0.0;
                 	}
                 	weigh_bridge_bill.Bill_Date=week_start;
                 	weigh_bridge_bill.Bill_Type="Employee Bill";
                 	weigh_bridge_bill.Employee_Vendor=employee_vendor_id;
                 	weigh_bridge_bill.Display_Name_Vendor="Hamid Ssenoga - 50";
                 	weigh_bridge_bill.Bill_Name="Weigh Bridge";
                 	weigh_bridge_bill.Bill_Number=weekly_bill_number;
                 	weigh_bridge_bill.Bill_Total=weekly_total;
                 	weigh_bridge_bill.Services_Total=weekly_total;
                 	weigh_bridge_bill.Total_Amount=weekly_total;
                 	weigh_bridge_bill.Amount_Due=weekly_total;
                 	weigh_bridge_bill.Balance_Due=round(balance_amount,2);
                 	weigh_bridge_bill.Bill_Status="Draft";
                 	if(paid_amount <= 0)
                 	{
                 		weigh_bridge_bill.Payment_Status="Not Paid";
                 	}
                 	else if(balance_amount <= 0)
                 	{
                 		weigh_bridge_bill.Payment_Status="Paid";
                 	}
                 	else
                 	{
                 		weigh_bridge_bill.Payment_Status="Partially Paid";
                 	}
                 	bill_id = weigh_bridge_bill.ID;
                 	// =====================================================
                 	// 9. DISTRIBUTE 1,000,000 AMONG THIS TRUCK'S TRIPS
                 	// =====================================================
                 	updated_count = 0;
                 	distributed_total = 0.0;
                 	current_trip_number = 0;
                 	for each  movement_rec in week_movements
                 	{
                 		movement_has_weigh_bridge = false;
                 		movement_services_total = 0.0;
                 		movement_display = ifnull(movement_rec.Display_Name_Voucher,"").trim();
                 		if(movement_rec.Line_Number != null)
                 		{
                 			if(movement_display != "")
                 			{
                 				movement_display = movement_display + " - " + movement_rec.Line_Number.toString();
                 			}
                 			else
                 			{
                 				movement_display = movement_rec.Line_Number.toString();
                 			}
                 		}
                 		for each  srv in movement_rec.Services
                 		{
                 			if(srv.Service != null)
                 			{
                 				service_name = ifnull(srv.Service.Service_Name,"").trim();
                 				if(service_name == "Weigh Bridge")
                 				{
                 					movement_has_weigh_bridge = true;
                 					current_trip_number = current_trip_number + 1;
                 					line_rate = rate_per_trip;
                 					// Last trip receives any rounding difference
                 					if(current_trip_number == weigh_bridge_trip_count)
                 					{
                 						line_rate = round(weekly_total - distributed_total,2);
                 					}
                 					srv.Quantity=1.0;
                 					srv.Rate=line_rate;
                 					srv.Bill=bill_id;
                 					srv.Display_Name_Bill="Weigh Bridge - " + weekly_bill_number;
                 					srv.Truck_Movement_Voucher=movement_rec.ID;
                 					srv.Display_Name_Voucher=movement_display;
                 					srv.Last_Synced_Group_ID=bill_id;
                 					srv.Last_Synced_Group_Amount=line_rate;
                 					movement_services_total = movement_services_total + line_rate;
                 					distributed_total = distributed_total + line_rate;
                 					updated_count = updated_count + 1;
                 				}
                 				else
                 				{
                 					movement_services_total = movement_services_total + ifnull(srv.Line_Total,0.0);
                 				}
                 			}
                 			else
                 			{
                 				movement_services_total = movement_services_total + ifnull(srv.Line_Total,0.0);
                 			}
                 		}
                 		// =================================================
                 		// 10. RECALCULATE PARENT MOVEMENT TOTALS
                 		// =================================================
                 		if(movement_has_weigh_bridge == true)
                 		{
                 			movement_rec.Service_Cost=round(movement_services_total,2);
                 			movement_rec.Line_Total=round(ifnull(movement_rec.Material_Cost,0.0) + ifnull(movement_rec.Service_Cost,0.0) + ifnull(movement_rec.Fuel_Cost,0.0) + ifnull(movement_rec.Labour_Cost,0.0),2);
                 			distance = ifnull(movement_rec.Line_Distance_Travelled,0.0);
                 			if(distance > 0)
                 			{
                 				movement_rec.Cost_Per_Odometer=round(movement_rec.Line_Total / distance,2);
                 			}
                 			else
                 			{
                 				movement_rec.Cost_Per_Odometer=0.0;
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// 11. VERIFY DISTRIBUTION
                 	// =====================================================
                 	distributed_total = round(distributed_total,2);
                 	if(distributed_total != weekly_total)
                 	{
                 		result.put("message","Weigh Bridge distribution for truck " + truck_plate + " does not equal UGX 1,000,000.");
                 		result.put("distributed_total",distributed_total);
                 		return result;
                 	}
                 	// =====================================================
                 	// 12. RETURN RESULTS
                 	// =====================================================
                 	result.put("bill_id",bill_id);
                 	result.put("lines_updated",updated_count);
                 	result.put("distributed_total",distributed_total);
                 	result.put("ok",true);
                 	result.put("message","Weekly Weigh Bridge bill for truck " + truck_plate + " was recalculated successfully.");
                 	return result;
                 }

void vendor.update_vendor_performance(int vendor_id)
{
                 	if(vendor_id == null)
                 	{
                 		return;
                 	}
                 	vendor_rec = Vendor_Register[ID == vendor_id];
                 	if(vendor_rec.ID == null)
                 	{
                 		return;
                 	}
                 	total_purchase_orders = 0;
                 	total_bills = 0;
                 	total_bill_amount = 0.0;
                 	total_payments_made = 0.0;
                 	outstanding_payables = 0.0;
                 	last_bill_date = null;
                 	last_payment_date = null;
                 	bill_list = Bill[Vendor == vendor_id];
                 	for each  bill_rec in bill_list
                 	{
                 		if(ifnull(bill_rec.Bill_Status,"") != "Cancelled")
                 		{
                 			total_bills = total_bills + 1;
                 			total_bill_amount = total_bill_amount + ifnull(bill_rec.Bill_Total,0.0);
                 			if(bill_rec.Bill_Date != null)
                 			{
                 				if(last_bill_date == null)
                 				{
                 					last_bill_date = bill_rec.Bill_Date;
                 				}
                 				else if(bill_rec.Bill_Date > last_bill_date)
                 				{
                 					last_bill_date = bill_rec.Bill_Date;
                 				}
                 			}
                 		}
                 	}
                 	payment_list = Payment_Made_Voucher[Vendor == vendor_id];
                 	for each  payment_rec in payment_list
                 	{
                 		if(ifnull(payment_rec.Payment_Made_Voucher_Status,"") != "Cancelled")
                 		{
                 			total_payments_made = total_payments_made + ifnull(payment_rec.Total_Amount_Paid,0.0);
                 			if(payment_rec.Payment_Made_Date != null)
                 			{
                 				if(last_payment_date == null)
                 				{
                 					last_payment_date = payment_rec.Payment_Made_Date;
                 				}
                 				else if(payment_rec.Payment_Made_Date > last_payment_date)
                 				{
                 					last_payment_date = payment_rec.Payment_Made_Date;
                 				}
                 			}
                 		}
                 	}
                 	outstanding_payables = total_bill_amount - total_payments_made;
                 	if(outstanding_payables < 0)
                 	{
                 		outstanding_payables = 0.0;
                 	}
                 	vendor_rec.Total_Bills=total_bills;
                 	vendor_rec.Total_Payments_Made=total_payments_made;
                 	vendor_rec.Outstanding_Payables=outstanding_payables;
                 	vendor_rec.Last_Bill_Date=last_bill_date;
                 	vendor_rec.Last_Payment_Date=last_payment_date;
                 }

void voucher.update_supervisor_voucher_summary(int voucher_id)
{
                 	if(voucher_id != null && voucher_id > 0)
                 	{
                 		current_voucher = Voucher_Register[ID == voucher_id];
                 		if(current_voucher.ID != null)
                 		{
                 			supervisor_ids = List();
                 			current_type = ifnull(current_voucher.Display_Name_Voucher_Type,"");
                 			if(current_type.contains("Supervisor Voucher"))
                 			{
                 				supervisor_ids.add(current_voucher.ID);
                 			}
                 			if(current_voucher.Issued_By != null)
                 			{
                 				issued_supervisor_id = current_voucher.Issued_By.ID;
                 				if(issued_supervisor_id != null && !supervisor_ids.contains(issued_supervisor_id))
                 				{
                 					supervisor_ids.add(issued_supervisor_id);
                 				}
                 			}
                 			if(current_voucher.Received_By != null)
                 			{
                 				received_supervisor_id = current_voucher.Received_By.ID;
                 				if(received_supervisor_id != null && !supervisor_ids.contains(received_supervisor_id))
                 				{
                 					supervisor_ids.add(received_supervisor_id);
                 				}
                 			}
                 			for each  supervisor_id in supervisor_ids
                 			{
                 				supervisor_voucher = Voucher_Register[ID == supervisor_id];
                 				if(supervisor_voucher.ID != null)
                 				{
                 					supervisor_type = ifnull(supervisor_voucher.Display_Name_Voucher_Type,"");
                 					if(supervisor_type.contains("Supervisor Voucher"))
                 					{
                 						issued_count = Voucher_Register[Issued_By == supervisor_id].count();
                 						returned_count = Voucher_Register[Received_By == supervisor_id].count();
                 						opening_count = 0;
                 						latest_previous_id = 0;
                 						latest_previous_time = null;
                 						if(supervisor_voucher.Employee != null && supervisor_voucher.Date_Time_In != null)
                 						{
                 							previous_supervisors = Voucher_Register[Employee == supervisor_voucher.Employee && Date_Time_In < supervisor_voucher.Date_Time_In];
                 							for each  previous_sv in previous_supervisors
                 							{
                 								previous_type = ifnull(previous_sv.Display_Name_Voucher_Type,"");
                 								if(previous_type.contains("Supervisor Voucher") && previous_sv.Date_Time_In != null)
                 								{
                 									if(latest_previous_time == null || previous_sv.Date_Time_In > latest_previous_time)
                 									{
                 										latest_previous_time = previous_sv.Date_Time_In;
                 										latest_previous_id = previous_sv.ID;
                 									}
                 								}
                 							}
                 							if(latest_previous_id > 0)
                 							{
                 								latest_previous = Voucher_Register[ID == latest_previous_id];
                 								if(latest_previous.ID != null)
                 								{
                 									opening_count = ifnull(latest_previous.Outstanding_Vouchers,0);
                 								}
                 							}
                 						}
                 						if(opening_count < 0)
                 						{
                 							opening_count = 0;
                 						}
                 						outstanding_count = opening_count + issued_count - returned_count;
                 						if(outstanding_count < 0)
                 						{
                 							outstanding_count = 0;
                 						}
                 						supervisor_voucher.Opening_Vouchers=opening_count;
                 						supervisor_voucher.Vouchers_Issued=issued_count;
                 						supervisor_voucher.Vouchers_Returned=returned_count;
                 						supervisor_voucher.Outstanding_Vouchers=outstanding_count;
                 						info "Supervisor Voucher: " + ifnull(supervisor_voucher.Voucher_Number,"");
                 						info "Opening: " + opening_count + ", Issued: " + issued_count + ", Returned: " + returned_count + ", Outstanding: " + outstanding_count;
                 					}
                 				}
                 			}
                 		}
                 	}
                 }
